/* Prexis extra curriculum. Merges into PREXIS_CONTENT. */
window.PREXIS_EXTRA = {"courses": [{"id": "web-intermediate", "subject": "Web development", "level": "Intermediate", "title": "Websites you run", "track": "web", "prereq": "web-pages", "rev": "2026-09-30", "unlock": {"after": "web-pages", "mastery": 55, "skill": "HTML & CSS"}, "blurb": "Ship it live, multi page sites, forms, SEO, motion, images, JavaScript, Git.", "units": [{"title": "Go live", "lessons": [{"title": "Put your site online", "keywords": ["ship", "deploy", "hosting", "netlify", "github", "pages", "vercel", "export", "live", "publish", "favicon"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free account on Netlify, GitHub or Vercel, and an email address to sign up. All three have free plans and none needs a card for a static site. Cost: free. This lesson asks for your live address at the end, so it is the first one you finish outside Prexis."}, {"type": "concept", "heading": "A static site is just files", "body": "Hosting is a computer that is always on and hands your files to anyone who asks. Your Workshop site is HTML and CSS with no server code, so any static host can serve it. GitHub Pages, Netlify and Vercel all have free plans with HTTPS built in."}, {"type": "mcq", "prompt": "Which files does a static host need to serve your Workshop site?", "options": ["A database and a server program", "An index.html with your page and styles", "Only the CSS file", "A copy of Prexis itself"], "answer": 1, "explain": "Static hosting serves files as they are. index.html is the file a host sends when someone opens your address."}, {"type": "concept", "heading": "Export my site", "body": "Open the Workshop and press Export my site. Prexis downloads one file, index.html. Your CSS is inlined in a style tag and your title, meta and icon tags move into the head. That single file is a complete website you can upload anywhere."}, {"type": "order", "prompt": "Put your site on Netlify Drop.", "items": ["Press Export my site in the Workshop", "Put index.html alone in a new folder", "Open app.netlify.com/drop and sign in", "Drag the folder onto the page", "Open the URL Netlify gives you"], "explain": "Export, package, upload, verify. The folder matters: Netlify publishes whatever folder you drop, and serves index.html at the root.", "codeItems": false, "orderNote": "Each step needs the one before it."}, {"type": "worked", "heading": "GitHub Pages without a terminal", "problem": "Publish the exported index.html from a GitHub repository using only the website.", "steps": ["Create a free account at github.com, then New repository. Name it yourname.github.io and make it public.", "On the repo page choose Add file, then Upload files. Drop index.html and press Commit changes.", "Open Settings, then Pages. Under Build and deployment pick Deploy from a branch, branch main, folder / (root). Save.", "Wait a minute, then open https://yourname.github.io. On Vercel the same file works: Add New, Project, import the repo, no build command, Deploy."], "takeaway": "Every free host follows the same shape: put index.html at the root, point the host at it, open the URL."}, {"type": "build", "prompt": "Get your page ready to ship: give it a title, a meta description and a favicon. Put them at the top of your HTML; Export moves them into the head for you. The Workshop cannot hold a favicon.ico file, so use an inline icon (a data: URL, as in the example) or a full https link to one. Then deploy it and paste your live URL.", "example": "<title>Casa Verde</title>\n<meta name=\"description\" content=\"Weeknight recipes that actually work.\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22%3E%3Ctext y=%22.9em%22 font-size=%2290%22%3E%F0%9F%8C%BF%3C/text%3E%3C/svg%3E\">", "explain": "A title for the tab, a description for search results, an icon for bookmarks. Your site now exists on the real internet.", "checks": [{"sel": "title", "exists": true, "label": "A title element"}, {"sel": "meta[name=\"description\"]", "attr": "content", "label": "A meta description with content"}, {"sel": "link[rel~=\"icon\"]", "attr": "href", "label": "A favicon the export carries: an inline data: icon or a full https URL", "match": "^(data:image/|https://)", "hint": "href=\"favicon.ico\" points at a file your export does not include. Use the inline icon from the example, or a full https URL to an icon."}, {"url": "liveUrl", "label": "Your live site address (starts with https://)", "kind": "site"}]}, {"type": "mcq", "prompt": "You uploaded your site but the root URL shows a 404 page. What is the most likely cause?", "options": ["DNS is broken", "The CSS is too long", "The file is not named index.html, or it sits inside a subfolder", "HTTPS is off"], "answer": 2, "explain": "Hosts look for index.html at the root of what you published. A file named mysite.html, or one tucked inside a folder, never gets served at /."}]}, {"title": "Multi page sites and navigation", "keywords": ["pages", "navigation", "nav", "links", "relative", "paths", "aria-current", "multi"], "steps": [{"type": "concept", "heading": "Paths are directions", "body": "href=\"about.html\" means: a file next to this one. href=\"../index.html\" means: up one folder, then index.html. href=\"/\" means: the root of the site. Relative links keep working on any host, any domain, and on your own computer.", "code": "<a href=\"about.html\">About</a>\n<a href=\"../index.html\">Home</a>"}, {"type": "mcq", "prompt": "You are on /blog/post.html. Which href reaches the home page at /index.html?", "options": ["index.html", "../index.html", "./blog/index.html", "post.html"], "answer": 1, "explain": "index.html alone would look inside /blog/. ../ climbs one folder to the root first."}, {"type": "concept", "heading": "Mark where you are", "body": "aria-current=\"page\" on the link to the current page tells screen readers you are here, and gives you a styling hook. Every page has the same nav; only the aria-current link changes."}, {"type": "build", "prompt": "Give your site a shared nav: a nav element with links to index.html, about.html and contact.html, and aria-current=\"page\" on the Home link. The Workshop holds one page; after you export, copy it to make about.html and contact.html and move aria-current in each copy.", "example": "<nav aria-label=\"Main\">\n  <a href=\"index.html\" aria-current=\"page\">Home</a>\n  <a href=\"about.html\">About</a>\n  <a href=\"contact.html\">Contact</a>\n</nav>", "explain": "One nav, copied to every page, with the current page marked. Visitors and screen readers both know where they are.", "checks": [{"sel": "nav a", "count": 3, "label": "A nav with at least 3 links"}, {"sel": "nav a[href$=\"about.html\"]", "exists": true, "label": "A link to about.html"}, {"sel": "nav a[href$=\"contact.html\"]", "exists": true, "label": "A link to contact.html"}, {"sel": "nav [aria-current=\"page\"]", "exists": true, "label": "One link marked aria-current=\"page\""}]}, {"type": "build", "prompt": "Style the current link so sighted visitors see it too: make nav links with aria-current=\"page\" bold (font-weight 600 or more).", "example": "nav [aria-current=\"page\"] {\n  font-weight: 700;\n  text-decoration: underline;\n}", "explain": "The attribute does double duty: meaning for assistive tech, a selector for your CSS.", "checks": [{"cssContains": "[aria-current", "label": "A rule targets [aria-current]"}, {"sel": "nav [aria-current=\"page\"]", "style": "fontWeight", "label": "The current link renders at weight 600 or more", "minPx": 600}]}, {"type": "order", "prompt": "Add a new page without breaking links.", "items": ["Export your current page as the template", "Copy it and rename the copy about.html", "Change the title, h1 and aria-current in the copy", "Add the about.html link to the nav on every page", "Click every nav link on the live site"], "explain": "Copy, change, link, verify. Skipping the last step is how broken links reach visitors.", "codeItems": false, "orderNote": "Each step needs the one before it: you cannot edit a copy before it exists, or test links before they are added."}, {"type": "mcq", "prompt": "Why use relative links like about.html instead of https://mysite.com/about.html for your own pages?", "options": ["Browsers require it", "They keep working on any host, preview URL or domain", "Search engines rank them higher", "They hide your domain name"], "answer": 1, "explain": "Relative links survive moving the site. Absolute links to your own domain break on preview deploys and on your laptop."}]}, {"title": "Forms that work", "keywords": ["forms", "form", "input", "label", "validation", "contact", "email", "netlify", "formspree", "required"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Optional: a free Netlify account (Netlify Forms) or a free Formspree account to receive the messages. Without one the form still validates in the browser; it just has nowhere to send. Cost: free."}, {"type": "concept", "heading": "The parts of a form", "body": "A form wraps inputs. Every input gets a label whose for matches the input's id. type=\"email\" and type=\"tel\" bring up the right phone keyboard. A button with type=\"submit\" sends it.", "code": "<form>\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <button type=\"submit\">Send</button>\n</form>"}, {"type": "mcq", "prompt": "Why should every input have a label whose for matches the input's id?", "options": ["It makes the field required", "It sends the label text to the server", "Screen readers announce it, and clicking the label focuses the input", "It styles the input automatically"], "answer": 2, "explain": "The pairing is meaning, not decoration. It also makes small checkboxes easier to hit, since the label becomes part of the target."}, {"type": "concept", "heading": "Validation you get for free", "body": "required, type=\"email\", minlength and pattern make the browser block a bad submit and explain why, with no JavaScript. Style the problem with :user-invalid so errors show after someone has typed, not on page load."}, {"type": "build", "prompt": "Add a contact form: an email input with id=\"email\" that is required, a label for it, a textarea for the message, and a submit button.", "example": "<form>\n  <label for=\"name\">Name</label>\n  <input id=\"name\" name=\"name\" required>\n  <label for=\"email\">Email</label>\n  <input id=\"email\" name=\"email\" type=\"email\" required>\n  <label for=\"message\">Message</label>\n  <textarea id=\"message\" name=\"message\" minlength=\"10\" required></textarea>\n  <button type=\"submit\">Send</button>\n</form>", "explain": "Labeled, typed and required. The browser now refuses an empty or malformed email before it leaves the page.", "checks": [{"sel": "form", "exists": true, "label": "A form element"}, {"sel": "form input#email[type=\"email\"][required]", "exists": true, "label": "A required email input with id=\"email\""}, {"sel": "form label[for=\"email\"]", "exists": true, "label": "A label whose for is \"email\""}, {"sel": "form textarea", "exists": true, "label": "A textarea for the message"}, {"sel": "form button[type=\"submit\"]", "exists": true, "label": "A submit button"}]}, {"type": "concept", "heading": "Sending without a server", "body": "A static host cannot run code, so a form service receives the submission. Netlify Forms: add data-netlify=\"true\" and a name to the form. Formspree: set action to your Formspree URL. Both want method=\"post\". A honeypot catches bots: a real text field that people cannot see, so only a bot fills it in. Hide it with the hidden attribute on a wrapper or with CSS. Do not use type=\"hidden\": many bots skip those, so they never take the bait."}, {"type": "build", "prompt": "Wire the form up: method=\"post\", either data-netlify=\"true\" or an action URL, and a honeypot: a real text input named bot-field that people cannot see (wrap it in an element with the hidden attribute, or hide it with CSS).", "example": "<form name=\"contact\" method=\"post\" data-netlify=\"true\" netlify-honeypot=\"bot-field\">\n  <p hidden><label>Skip this <input name=\"bot-field\"></label></p>\n  ...\n</form>", "explain": "Posted, routed to a service, and guarded against the laziest bots. Submit it once on the live site to confirm it arrives.", "checks": [{"sel": "form[method=\"post\" i]", "exists": true, "label": "The form uses method=\"post\""}, {"sel": "form[data-netlify], form[action]", "exists": true, "label": "The form has data-netlify or an action"}, {"sel": "form input[name=\"bot-field\"], form input[name=\"_gotcha\"]", "exists": true, "label": "A honeypot input (bot-field or _gotcha)"}, {"sel": "form input[name=\"bot-field\"][type=\"hidden\" i], form input[name=\"_gotcha\"][type=\"hidden\" i]", "none": true, "label": "The honeypot is a real text field, not type=\"hidden\"", "hint": "Bots often skip type=\"hidden\" inputs. Use a normal input and hide it from people instead."}, {"sel": "form input[name=\"bot-field\"], form input[name=\"_gotcha\"]", "invisible": true, "label": "People cannot see the honeypot", "hint": "Wrap it in <p hidden>...</p>, or give it a class your CSS hides with display: none."}]}, {"type": "code", "prompt": "Browsers validate, but your code should too. Write formErrors(fields) that returns an array of the field names that are invalid, in this order: \"name\" if empty after trimming, \"email\" if it lacks an @ or a dot after the @, \"message\" if shorter than 10 characters after trimming.", "starter": "function formErrors(fields) {\n  const errors = [];\n  \n  return errors;\n}", "tests": [{"call": "formErrors({ name: \"Ada\", email: \"ada@example.com\", message: \"Hello there, friend\" })", "expect": []}, {"call": "formErrors({ name: \"  \", email: \"ada@example.com\", message: \"Hello there, friend\" })", "expect": ["name"]}, {"call": "formErrors({ name: \"Ada\", email: \"ada.example.com\", message: \"Hi\" })", "expect": ["email", "message"]}, {"call": "formErrors({ name: \"Ada\", email: \"ada@example\", message: \"Long enough message\" })", "expect": ["email"]}], "solution": "function formErrors(fields) {\n  const errors = [];\n  if (!String(fields.name || \"\").trim()) errors.push(\"name\");\n  const email = String(fields.email || \"\");\n  const at = email.indexOf(\"@\");\n  if (at < 1 || email.indexOf(\".\", at) < 0) errors.push(\"email\");\n  if (String(fields.message || \"\").trim().length < 10) errors.push(\"message\");\n  return errors;\n}", "explain": "Trim before testing, and return every problem at once so the person fixes them in one pass."}]}]}, {"title": "Polish", "lessons": [{"title": "Semantic HTML, SEO, and sharing", "keywords": ["seo", "meta", "description", "open", "graph", "sharing", "semantic", "article", "section", "time", "search"], "steps": [{"type": "concept", "heading": "What search results show", "body": "The title element becomes the blue link. The meta description often becomes the text under it. One clear h1 tells search engines and screen readers what the page is about.", "code": "<title>Casa Verde: weeknight recipes</title>\n<meta name=\"description\" content=\"Thirty-minute dinners that actually work.\">"}, {"type": "mcq", "prompt": "Which tag usually sets the text under your link in a search result?", "options": ["<meta name=\"keywords\">", "<meta name=\"description\">", "<h2>", "<meta charset=\"utf-8\">"], "answer": 1, "explain": "Search engines ignore the keywords tag today. The description is your pitch in the results page."}, {"type": "concept", "heading": "Previews when people share", "body": "Open Graph tags control the card you see when a link is pasted into a chat or social app: og:title, og:description and og:image. The image must be an absolute https URL, ideally 1200 by 630 pixels."}, {"type": "build", "prompt": "Add sharing tags: a meta description, og:title, and an og:image whose content is an absolute https URL.", "example": "<meta name=\"description\" content=\"Weeknight recipes that actually work.\">\n<meta property=\"og:title\" content=\"Casa Verde\">\n<meta property=\"og:description\" content=\"Weeknight recipes that actually work.\">\n<meta property=\"og:image\" content=\"https://example.com/share.png\">", "explain": "Paste your live URL into a chat after you redeploy. The card you see is these tags.", "checks": [{"sel": "meta[name=\"description\"]", "attr": "content", "label": "A meta description"}, {"sel": "meta[property=\"og:title\"]", "attr": "content", "label": "An og:title tag"}, {"sel": "meta[property=\"og:image\"]", "attr": "content", "label": "og:image uses an https URL", "contains": "https://"}]}, {"type": "concept", "heading": "Elements that say what they are", "body": "article: a piece that makes sense alone, like a post or recipe. section: a themed group with its own heading. aside: related but not essential. time with a datetime attribute: a date machines can read."}, {"type": "build", "prompt": "Add a semantic content block: an article, a section with its own heading, and a time element with a datetime attribute.", "example": "<section>\n  <h2>Latest</h2>\n  <article class=\"card\">\n    <h3>Lemon pasta</h3>\n    <p>Posted <time datetime=\"2026-09-30\">30 September</time></p>\n  </article>\n</section>", "explain": "The page looks the same, but now it describes itself to search engines and assistive tech.", "checks": [{"sel": "article", "exists": true, "label": "An article element"}, {"sel": "section h2, section h3", "exists": true, "label": "A section with a heading inside"}, {"sel": "time", "attr": "datetime", "label": "A time element with datetime"}]}, {"type": "concept", "heading": "Landmarks and headings", "body": "header, nav, main and footer are landmarks: screen reader users jump between them, and later lessons build on them. One main per page holds the content that is unique to it. Cards read better with a heading of their own, so people scanning the page, or a list of headings, can tell them apart.", "code": "<main>\n  <h1>Casa Verde</h1>\n  <div class=\"card\"><h3>Soups</h3><p>Warm bowls.</p></div>\n</main>\n<footer>\n  <p>Casa Verde, weeknight recipes</p>\n</footer>"}, {"type": "build", "prompt": "Give the page its landmarks: wrap your content (everything after the nav) in a main element, add a footer at the end, and give at least three of your cards a heading (h2 or h3).", "example": "<nav>...</nav>\n<main>\n  <h1>Casa Verde</h1>\n  ...\n  <div class=\"gallery\">\n    <div class=\"card\"><h3>Soups</h3><p>Warm bowls</p></div>\n    <div class=\"card\"><h3>Pasta</h3><p>Ten minutes</p></div>\n    <div class=\"card\"><h3>Salads</h3><p>Crunchy</p></div>\n  </div>\n</main>\n<footer>\n  <p>Casa Verde, weeknight recipes</p>\n</footer>", "explain": "Your page now has the structure every later lesson builds on: a main to skip to, a footer for links, and cards people can tell apart.", "checks": [{"sel": "main", "exists": true, "label": "A main element"}, {"sel": "footer", "exists": true, "label": "A footer element"}, {"sel": ".card h2, .card h3", "count": 3, "label": "At least three cards with a heading", "hint": "Add an h3 at the top of each card, for example <h3>Soups</h3>."}]}, {"type": "order", "prompt": "Order what a crawler does with your page, in the model from this lesson.", "items": ["Fetch the HTML", "Read the title and meta description", "Read the headings and main content", "Follow the links to more pages"], "explain": "It has to fetch before it reads, and it finds new pages through the links it reads. That is why internal links matter for SEO.", "codeItems": false, "groups": [[1, 2]], "orderNote": "Fetch comes first and following links comes last. The two reading steps can swap."}]}, {"title": "The cascade, specificity, and states", "keywords": ["cascade", "specificity", "hover", "focus", "pseudo", "states", "before", "after", "important"], "steps": [{"type": "concept", "heading": "Who wins", "body": "When two rules set the same property, the browser compares specificity: inline style, then ids, then classes, attributes and pseudo-classes, then elements. On a tie, the later rule wins.", "code": "#menu a { color: red; }   /* 1 id, 1 element */\n.nav a { color: blue; }   /* 1 class, 1 element */"}, {"type": "mcq", "prompt": "Both rules match the same link. Which color wins?", "options": ["blue, because .nav a comes later", "red, because one id outweighs any number of classes", "They tie, so the browser picks", "Neither, links ignore color"], "answer": 1, "explain": "Source order only breaks ties. An id beats classes no matter where it sits."}, {"type": "concept", "heading": "States and pseudo-elements", "body": ":hover and :focus-visible react to the visitor. ::before and ::after add decoration without new HTML, and they need a content property to appear.", "code": ".card:hover { transform: translateY(-2px); }\na:focus-visible { outline: 3px solid; }\n.card h3::before { content: \"# \"; }"}, {"type": "build", "prompt": "Add interactive states: a .card:hover rule, a :focus-visible rule, and a ::before or ::after with content. Do it without !important.", "example": ".card:hover {\n  box-shadow: 0 4px 12px rgba(0,0,0,.15);\n}\na:focus-visible {\n  outline: 3px solid #4f46e5;\n  outline-offset: 2px;\n}\n.card h3::after {\n  content: \" >\";\n}", "explain": "Hover for mice, focus-visible for keyboards, and decoration that stays out of your HTML.", "checks": [{"cssContains": ".card:hover", "label": "A .card:hover rule"}, {"cssContains": ":focus-visible", "label": "A :focus-visible rule"}, {"cssContains": "content:", "label": "A pseudo-element with content"}, {"cssContains": "!important", "label": "No !important in your stylesheet", "negate": true}]}, {"type": "mcq", "prompt": "A style refuses to apply. What is the best first move?", "options": ["Inspect the element in DevTools and see which rule wins", "Add !important", "Rewrite the stylesheet", "Clear the browser cache"], "answer": 0, "explain": "DevTools shows every matching rule, crossed out or not. Guessing with !important hides the cause."}, {"type": "order", "prompt": "Order these from lowest to highest specificity.", "items": ["p", ".card", ".card p", "#main", "style=\"\" (inline)"], "explain": "Elements, then classes, then a class plus element, then an id, then inline style.", "codeItems": true, "orderNote": "Order matters: each one outweighs every item before it."}]}, {"title": "Motion with care", "keywords": ["animation", "transition", "keyframes", "motion", "reduced", "transform", "opacity"], "steps": [{"type": "concept", "heading": "Two kinds of motion", "body": "A transition animates between two states when something changes, like a hover. @keyframes defines a sequence that runs on its own, like an entrance.", "code": ".card { transition: transform 200ms ease; }\n@keyframes rise { from { opacity: 0; transform: translateY(8px); } }"}, {"type": "mcq", "prompt": "Which properties are cheapest to animate?", "options": ["width and height", "top and left", "transform and opacity", "margin and padding"], "answer": 2, "explain": "The browser can move and fade a layer without redoing layout. Animating size or position forces layout on every frame."}, {"type": "concept", "heading": "Respect the setting", "body": "Some people get dizzy or sick from motion. Operating systems let them ask for less, and CSS reads it as prefers-reduced-motion. Honor it by removing or shortening animations."}, {"type": "build", "prompt": "Add motion: a transition on .card, a hover rule that uses transform, an @keyframes animation, and a prefers-reduced-motion rule that turns motion down.", "example": ".card { transition: transform 200ms ease; }\n.card:hover { transform: translateY(-3px); }\n@keyframes rise {\n  from { opacity: 0; transform: translateY(8px); }\n}\nh1 { animation: rise 400ms ease both; }\n@media (prefers-reduced-motion: reduce) {\n  .card, h1 { animation: none; transition: none; }\n}", "explain": "Motion that helps, and an off switch for the people it hurts.", "checks": [{"sel": ".card", "style": "transitionDuration", "label": ".card has a transition", "not": "0s"}, {"cssContains": "transform", "label": "A rule uses transform"}, {"cssContains": "@keyframes", "label": "An @keyframes animation"}, {"cssContains": "prefers-reduced-motion", "label": "A prefers-reduced-motion rule"}]}, {"type": "mcq", "prompt": "A visitor says your page animation makes them dizzy. What should the site do?", "options": ["Make the animation faster", "Honor prefers-reduced-motion and stop or tone down the motion", "Add a warning banner", "Nothing, it is their device"], "answer": 1, "explain": "They already told their device. The media query is how your site listens."}, {"type": "order", "prompt": "Add a safe animation.", "items": ["Pick one element where motion helps", "Animate only transform or opacity", "Keep UI feedback short, about 200 to 300ms", "Add a reduced-motion override", "Test with reduced motion turned on"], "explain": "Choose with purpose, animate cheaply, keep it brief, give an off switch, then test.", "codeItems": false, "groups": [[1, 2]], "orderNote": "Steps 2 and 3 can swap; the check accepts either."}]}]}, {"title": "Run it", "lessons": [{"title": "Images done right", "keywords": ["images", "srcset", "picture", "webp", "avif", "lazy", "responsive", "formats"], "steps": [{"type": "concept", "heading": "Pick the right format", "body": "JPEG for photos, PNG for screenshots with sharp edges, SVG for logos and icons, WebP or AVIF for smaller photos with the same quality. A 4000 pixel photo shown 800 pixels wide wastes most of its bytes."}, {"type": "mcq", "prompt": "Which format fits a logo best?", "options": ["JPEG", "SVG", "GIF", "BMP"], "answer": 1, "explain": "SVG is drawn from shapes, so it stays sharp at every size and is usually tiny."}, {"type": "concept", "heading": "Let the browser choose", "body": "srcset lists the same image at several widths. sizes says how wide it displays. The browser downloads the smallest file that looks sharp. picture with source elements offers new formats with a fallback.", "code": "<picture>\n  <source type=\"image/webp\" srcset=\"hero-800.webp 800w, hero-1600.webp 1600w\">\n  <img src=\"hero-800.jpg\" srcset=\"hero-800.jpg 800w, hero-1600.jpg 1600w\" sizes=\"100vw\" width=\"1600\" height=\"900\" alt=\"Lemon pasta in a blue bowl\">\n</picture>"}, {"type": "build", "prompt": "Make one image responsive: wrap it in picture with a source element, give the img a srcset, width and height, lazy-load an image that sits further down the page, and add img { max-width: 100%; height: auto; } to your CSS so a 1200 pixel image shrinks to fit a phone instead of widening the page. The Workshop cannot hold image files, so use full https image URLs, like the picsum.photos ones in the example; on your own host you can swap in files you upload.", "example": "<picture>\n  <source type=\"image/webp\" srcset=\"https://picsum.photos/id/292/800/450.webp 800w\">\n  <img src=\"https://picsum.photos/id/292/800/450\" srcset=\"https://picsum.photos/id/292/800/450 800w, https://picsum.photos/id/292/1600/900 1600w\" sizes=\"100vw\" width=\"800\" height=\"450\" alt=\"Ingredients on a table\">\n</picture>\n<img src=\"https://picsum.photos/id/429/600/400\" loading=\"lazy\" width=\"600\" height=\"400\" alt=\"A finished dish\">\n\n/* CSS */\nimg {\n  max-width: 100%;\n  height: auto;\n}", "explain": "Phones get small files, big screens get sharp ones, and images below the fold wait until someone scrolls.", "checks": [{"sel": "picture source", "exists": true, "label": "A picture element with a source"}, {"sel": "img[srcset]", "attr": "srcset", "label": "An img with srcset"}, {"sel": "img[width][height]", "exists": true, "label": "An img with width and height"}, {"sel": "img[loading=\"lazy\"]", "exists": true, "label": "An img with loading=\"lazy\""}, {"sel": "img", "style": "maxWidth", "label": "Images shrink to fit: img has max-width: 100%", "equals": "100%", "hint": "Width and height attributes reserve space, but without max-width a big image runs off the side of a phone. Add img { max-width: 100%; height: auto; }."}, {"sel": "img", "attr": "src", "label": "Every image uses a full https URL, so it loads", "match": "^(https://|data:image/)", "every": true, "hint": "A name like hero.jpg points at a file the Workshop and your export do not have, so it shows as a broken image. Use a full https URL, such as https://picsum.photos/id/292/800/450."}, {"sel": "img[srcset], source[srcset]", "attr": "srcset", "label": "Every srcset lists full https URLs", "match": "^\\s*(https://|data:image/)\\S+(\\s+\\d+(\\.\\d+)?[wx])?\\s*(,\\s*(https://|data:image/)\\S+(\\s+\\d+(\\.\\d+)?[wx])?\\s*)*$", "every": true, "hint": "Each entry is a full https URL and a width, separated by commas: https://picsum.photos/id/292/800/450 800w, https://picsum.photos/id/292/1600/900 1600w"}]}, {"type": "mcq", "prompt": "Why set width and height on images?", "options": ["They make the file smaller", "The browser reserves the space, so text does not jump when the image arrives", "They are required for alt text to work", "They turn on lazy loading"], "answer": 1, "explain": "Without dimensions the page reflows when each image loads. That jump is layout shift, and it is measured."}, {"type": "order", "prompt": "Add a new photo to the site properly.", "items": ["Resize the original to the largest size you show", "Export WebP plus a JPEG fallback", "Add width, height and alt", "Add srcset and sizes", "Lazy-load it if it sits below the fold"], "explain": "Prepare the files first, then describe them in HTML.", "codeItems": false, "groups": [[2, 3, 4]], "orderNote": "The HTML attributes in steps 3 to 5 can go in any order; the check accepts them."}]}, {"title": "A little JavaScript on your page", "keywords": ["javascript", "dom", "events", "menu", "dark", "mode", "theme", "localstorage", "toggle", "script"], "steps": [{"type": "concept", "heading": "Three moves cover most page scripts", "body": "Find an element with querySelector, listen with addEventListener, change something with classList or setAttribute. Put the script at the end of body, or use defer on an external file. Use type=\"module\" on your script tags: each module keeps its names to itself, so two scripts can both have a btn without crashing. The Prexis preview never runs scripts, for your safety; checks read your code, the code step below runs your logic, and your exported site runs it for real.", "code": "const btn = document.querySelector(\".menu-toggle\");\nbtn.addEventListener(\"click\", () => {\n  const open = btn.getAttribute(\"aria-expanded\") === \"true\";\n  btn.setAttribute(\"aria-expanded\", String(!open));\n  document.querySelector(\"nav\").classList.toggle(\"open\");\n});"}, {"type": "mcq", "prompt": "Why use a button element for the menu toggle instead of a div?", "options": ["Divs cannot have click handlers", "A button is focusable and works with Enter and Space for free", "Buttons load faster", "Divs break CSS"], "answer": 1, "explain": "Keyboard support and the correct role come built in. A clickable div needs all of that rebuilt by hand."}, {"type": "build", "prompt": "Add a mobile menu: a button with class menu-toggle and aria-expanded=\"false\" just before your nav, a script that toggles an open class on the nav with classList.toggle, and CSS that hides the nav on narrow screens until it has the open class. The lesson preview is narrow, so your nav will tuck away behind the button there; export and open the page at phone width to watch the button open it.", "example": "<button class=\"menu-toggle\" aria-expanded=\"false\">Menu</button>\n<nav>...</nav>\n<script type=\"module\">\n  const btn = document.querySelector(\".menu-toggle\");\n  const nav = document.querySelector(\"nav\");\n  btn.addEventListener(\"click\", () => {\n    const open = nav.classList.toggle(\"open\");\n    btn.setAttribute(\"aria-expanded\", String(open));\n  });\n</script>\n\n/* CSS */\n.menu-toggle { display: none; }\n@media (max-width: 600px) {\n  .menu-toggle { display: inline-block; }\n  nav { display: none; }\n  nav.open { display: flex; flex-direction: column; gap: 8px; }\n}", "explain": "aria-expanded tells screen readers the menu state; the open class tells your CSS to show the nav. On wide screens the button hides and the nav stays put.", "checks": [{"sel": "button.menu-toggle", "exists": true, "label": "A button with class menu-toggle"}, {"sel": "button.menu-toggle", "attr": "aria-expanded", "label": "The button has aria-expanded"}, {"sel": "script", "exists": true, "label": "A script element"}, {"htmlContains": "classList.toggle", "label": "The script uses classList.toggle"}, {"cssContains": "nav.open", "label": "CSS shows the nav when it has the open class", "hint": "Without CSS for nav.open the button flips a class nobody styles, so nothing visibly happens. Inside @media (max-width: 600px), hide nav and show nav.open, as in the example."}]}, {"type": "concept", "heading": "Dark mode from your tokens", "body": "You already keep colors in custom properties. Redefine them under [data-theme=\"dark\"] on the html element, flip that attribute with a button, and save the choice in localStorage so it sticks.", "code": "[data-theme=\"dark\"] {\n  --paper: #1d1f24;\n  --ink: #f1efe8;\n}"}, {"type": "code", "prompt": "Write pickTheme(saved, prefersDark). Return saved only when it is exactly \"light\" or \"dark\"; anything else that was saved (null, or a stray value like \"purple\") is ignored. Otherwise return \"dark\" if prefersDark is true, else \"light\".", "starter": "function pickTheme(saved, prefersDark) {\n  \n}", "tests": [{"call": "pickTheme(\"dark\", false)", "expect": "dark"}, {"call": "pickTheme(\"light\", true)", "expect": "light"}, {"call": "pickTheme(null, true)", "expect": "dark"}, {"call": "pickTheme(\"purple\", false)", "expect": "light"}], "solution": "function pickTheme(saved, prefersDark) {\n  if (saved === \"light\" || saved === \"dark\") return saved;\n  return prefersDark ? \"dark\" : \"light\";\n}", "explain": "A saved choice beats the system setting; the system setting beats your default."}, {"type": "build", "prompt": "Wire dark mode: a [data-theme=\"dark\"] rule in your CSS that changes your tokens, a button with class theme-toggle, and a script that saves the choice with localStorage.", "example": "<button class=\"theme-toggle\">Dark mode</button>\n<script type=\"module\">\n  const root = document.documentElement;\n  root.dataset.theme = localStorage.getItem(\"theme\") || \"light\";\n  document.querySelector(\".theme-toggle\").addEventListener(\"click\", () => {\n    root.dataset.theme = root.dataset.theme === \"dark\" ? \"light\" : \"dark\";\n    localStorage.setItem(\"theme\", root.dataset.theme);\n  });\n</script>\n\n/* CSS */\n[data-theme=\"dark\"] { --paper: #1d1f24; --ink: #f1efe8; }", "explain": "Export and open it in a browser: the toggle works and remembers your choice after a reload.", "checks": [{"cssContains": "[data-theme=\"dark\"]", "label": "A [data-theme=\"dark\"] rule in your CSS"}, {"sel": "button.theme-toggle", "exists": true, "label": "A button with class theme-toggle"}, {"htmlContains": "localStorage", "label": "The script saves the choice in localStorage"}]}, {"type": "mcq", "prompt": "The page flashes light for a moment before going dark. What is the fix?", "options": ["Add a transition to body", "Set data-theme in a tiny script in the head, before the page paints", "Load the script with async", "Use a darker light theme"], "answer": 1, "explain": "A script at the end of body runs after the first paint. Reading the saved theme in the head sets it before anything shows."}]}, {"title": "Git and GitHub for real", "keywords": ["git", "github", "commit", "push", "repository", "repo", "version", "control", "pages", "capstone"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free GitHub account and Git on your computer (git-scm.com; on a Mac, typing git in Terminal offers to install it). GitHub Desktop works too if you would rather click than type. Cost: free."}, {"type": "concept", "heading": "Snapshots with a story", "body": "Git saves snapshots of your files called commits, each with a message saying why. GitHub stores your repository online, shows the history, and can publish it with GitHub Pages. If a change breaks the site, you can go back to any commit."}, {"type": "order", "prompt": "Order the everyday Git loop.", "items": ["Edit your files", "git add index.html", "git commit -m \"Add contact form\"", "git push"], "explain": "Change, stage, snapshot, upload. Nothing reaches GitHub until you push.", "codeItems": true, "orderNote": "Each command works on the result of the one before it."}, {"type": "worked", "heading": "From a folder to a published repo", "problem": "Your exported index.html sits in a folder called my-site. Put it on GitHub from a terminal.", "steps": ["cd my-site, then git init to start a repository.", "git add index.html, then git commit -m \"First version\".", "Create an empty repo on github.com, then git remote add origin https://github.com/you/my-site.git", "git branch -M main, then git push -u origin main. In the repo, Settings, Pages, deploy from main. Each future push updates the site."], "takeaway": "Once the remote is set, publishing is git push.", "code": "git init\ngit add index.html\ngit commit -m \"First version\"\ngit branch -M main\ngit remote add origin https://github.com/you/my-site.git\ngit push -u origin main"}, {"type": "mcq", "prompt": "Which commit message helps you most six months from now?", "options": ["stuff", "fix", "Add contact form with email validation", "asdfgh"], "answer": 2, "explain": "Say what changed and why in a short line. History is only searchable if the messages mean something."}, {"type": "mcq", "prompt": "You pushed a change but the live site still shows the old version. What do you check first?", "options": ["Delete the repository", "The Pages or Actions tab, to see if the deploy finished or failed", "Buy a new domain", "Rewrite the commit"], "answer": 1, "explain": "Publishing takes a minute and can fail. The deploy status tells you which one happened."}, {"type": "build", "prompt": "Intermediate capstone. Your site should have everything from this level: a nav with 3 links and aria-current, a contact form, a meta description and og:image, a favicon, a responsive image, a theme toggle, and a link to your GitHub repo in your footer. Commit it, push it, and paste your repo URL.", "example": "<footer>\n  <p>Source on <a href=\"https://github.com/you/my-site\">GitHub</a></p>\n</footer>", "explain": "A real multi page site, live, in Git, with a form and dark mode. You run a website now.", "checks": [{"sel": "nav a", "count": 3, "label": "Nav with at least 3 links"}, {"sel": "nav [aria-current=\"page\"]", "exists": true, "label": "Current page marked with aria-current"}, {"sel": "form input[type=\"email\"]", "exists": true, "label": "A contact form with an email input"}, {"sel": "meta[name=\"description\"]", "attr": "content", "label": "A meta description"}, {"sel": "meta[property=\"og:image\"]", "attr": "content", "label": "An og:image tag"}, {"sel": "link[rel~=\"icon\"]", "attr": "href", "label": "A favicon link (inline data: or https)", "match": "^(data:image/|https://)"}, {"sel": "img[srcset]", "exists": true, "label": "A responsive image with srcset"}, {"sel": "button.theme-toggle", "exists": true, "label": "A theme toggle button"}, {"sel": "footer a[href*=\"github.com\"]", "exists": true, "label": "A footer link to your GitHub repo"}, {"confirm": true, "label": "I committed and pushed this version to GitHub"}, {"url": "repoUrl", "label": "Your GitHub repo URL", "kind": "repo"}]}]}]}]}, {"id": "web-advanced", "subject": "Web apps", "level": "Advanced", "title": "Web apps with real tools", "track": "web", "prereq": "web-intermediate", "rev": "2026-09-30", "unlock": {"after": "web-intermediate", "mastery": 85, "skill": "Web development"}, "blurb": "Modern CSS, modules, fetch, Vite, deploy from Git, your own domain, speed, accessibility, CI.", "units": [{"title": "Modern front end", "lessons": [{"title": "Modern CSS architecture", "keywords": ["css", "architecture", "layer", "container", "queries", "has", "where", "bem"], "steps": [{"type": "concept", "heading": "Names that scale", "body": "Pick one naming pattern and keep it. BEM names a block, its elements and variants: .card, .card__title, .card--featured. Anyone reading the HTML knows which CSS owns it."}, {"type": "concept", "heading": "Newer tools that remove hacks", "body": "@layer sets the order your CSS groups win in, so a utility class beats a component without specificity fights. Container queries style a component by the width of its container, not the window. :has() styles a parent based on what it contains.", "code": "@layer reset, base, components, utilities;\n.cards { container-type: inline-size; }\n@container (min-width: 500px) { .card { display: flex; } }\n.card:has(img) { padding-top: 0; }"}, {"type": "mcq", "prompt": "When is a container query better than a media query?", "options": ["When the whole page changes at a phone width", "When the same component appears in a wide main area and a narrow sidebar", "When printing", "Never, they do the same thing"], "answer": 1, "explain": "Media queries know the window. A card does not care about the window; it cares about the space it was given."}, {"type": "build", "prompt": "Refactor your CSS: declare layers with @layer, give one card heading the class card__title (your cards got headings in Semantic HTML, SEO, and sharing; add an h3 to a card if it has none), and make your card wrapper a container with an @container rule.", "example": "@layer reset, base, components;\n@layer components {\n  .cards { container-type: inline-size; }\n  @container (min-width: 500px) {\n    .card { display: flex; gap: 12px; }\n  }\n}\n\n<h3 class=\"card__title\">Lemon pasta</h3>", "explain": "Your styles now have an explicit order and your cards adapt to wherever you put them.", "checks": [{"cssContains": "@layer", "label": "An @layer rule"}, {"sel": ".card__title", "exists": true, "label": "An element with class card__title", "hint": "Add the class to a heading inside a card: <h3 class=\"card__title\">Soups</h3>."}, {"cssContains": "container-type", "label": "A container-type declaration"}, {"cssContains": "@container", "label": "An @container rule"}]}, {"type": "build", "prompt": "Use smarter selectors: make sure at least one card contains an image so .card:has(img) matches (move an image into a card, or add one), and write a :where( rule.", "example": ".card:has(img) { padding-top: 0; }\n:where(.card, .panel) h3 { margin-top: 0; }", "explain": ":has() replaces the extra class you used to add by hand. :where() groups selectors with zero specificity, so it never fights your components.", "checks": [{"sel": ".card:has(img)", "exists": true, "label": "A card that contains an image"}, {"cssContains": ":has(", "label": "A rule that uses :has("}, {"cssContains": ":where(", "label": "A rule that uses :where("}]}, {"type": "order", "prompt": "Order the layers from first (weakest) to last (strongest).", "items": ["reset", "base", "components", "utilities"], "explain": "Later layers win. Utilities sit last so a single class can override a component on purpose.", "codeItems": true, "orderNote": "Order matters here: in @layer, the order you declare is the order that wins."}]}, {"title": "JavaScript modules and components", "keywords": ["modules", "import", "export", "components", "template", "literals", "render", "textcontent", "innerhtml"], "steps": [{"type": "concept", "heading": "Modules keep code apart", "body": "type=\"module\" scripts have their own scope, run after the HTML is parsed, and can import from other files. Each file exports what others may use.", "code": "// projects.js\nexport const projects = [{ title: \"Lemon pasta\", summary: \"Ten minutes\" }];\n\n// main.js\nimport { projects } from \"./projects.js\";"}, {"type": "mcq", "prompt": "What does type=\"module\" change about a script?", "options": ["Nothing, it is only a label", "It gets its own scope, is deferred, and can use import", "It runs before the HTML loads", "It can only contain JSON"], "answer": 1, "explain": "Module scripts behave like defer by default and never leak variables onto window."}, {"type": "concept", "heading": "Data in, markup out", "body": "Keep repeated content as an array of objects. A small function turns one object into markup, and map turns the array into a page section. Change the data, the page follows.", "code": "const html = projects.map(renderCard).join(\"\");"}, {"type": "code", "prompt": "Write renderCard(p) so it returns exactly: <article class=\"card\"><h3 class=\"card__title\">TITLE</h3><p>SUMMARY</p></article> using p.title and p.summary. Use a template literal.", "starter": "function renderCard(p) {\n  return ``;\n}", "tests": [{"call": "renderCard({ title: \"Lemon pasta\", summary: \"Ten minutes\" })", "expect": "<article class=\"card\"><h3 class=\"card__title\">Lemon pasta</h3><p>Ten minutes</p></article>"}, {"call": "[{ title: \"A\", summary: \"1\" }, { title: \"B\", summary: \"2\" }].map(renderCard).join(\"\")", "expect": "<article class=\"card\"><h3 class=\"card__title\">A</h3><p>1</p></article><article class=\"card\"><h3 class=\"card__title\">B</h3><p>2</p></article>"}], "solution": "function renderCard(p) {\n  return `<article class=\"card\"><h3 class=\"card__title\">${p.title}</h3><p>${p.summary}</p></article>`;\n}", "explain": "One function, any number of cards. This is the core idea behind every component framework."}, {"type": "build", "prompt": "Make your cards data-driven: add a module script that defines renderCard and maps over an array into your card grid. That is the .gallery you built in Grid for real layouts, or a .grid if you named it that. Keep three static .card elements inside it as the fallback; the preview does not run scripts, and your exported site replaces them.", "example": "<div class=\"gallery\">\n  <article class=\"card\">...</article>\n  <article class=\"card\">...</article>\n  <article class=\"card\">...</article>\n</div>\n<script type=\"module\">\n  const projects = [{ title: \"Lemon pasta\", summary: \"Ten minutes\" }];\n  const renderCard = (p) => `<article class=\"card\"><h3 class=\"card__title\">${p.title}</h3><p>${p.summary}</p></article>`;\n  document.querySelector(\".gallery, .grid\").innerHTML = projects.map(renderCard).join(\"\");\n</script>", "explain": "The markup now comes from data. Adding a project is one line in an array, not a copy and paste.", "checks": [{"sel": "script[type=\"module\"]", "exists": true, "label": "A script with type=\"module\""}, {"htmlContains": "renderCard", "label": "A renderCard function"}, {"htmlContains": ".map(", "label": "The data is rendered with map"}, {"sel": ".grid .card, .gallery .card", "count": 3, "label": "Three fallback cards inside your .gallery or .grid", "hint": "The Beginner grid is class gallery. Keep at least three .card elements inside it (or inside a .grid)."}]}, {"type": "concept", "heading": "textContent for anything a person typed", "body": "innerHTML parses its string as HTML. If that string came from a visitor, they can inject a script. textContent inserts plain text and can never become markup. Use template literals for your own trusted data, and textContent for theirs."}, {"type": "mcq", "prompt": "Which is safest for putting a visitor's name on the page?", "options": ["el.innerHTML = name", "el.textContent = name", "document.write(name)", "el.outerHTML = name"], "answer": 1, "explain": "textContent never parses HTML, so a name like <img onerror=...> shows as text instead of running."}, {"type": "order", "prompt": "Order the render flow.", "items": ["Load the data", "Build markup or elements from it", "Append them to the page", "Attach event listeners"], "explain": "Listeners need elements to attach to, and elements need data to be built from.", "codeItems": false, "orderNote": "Each step depends on the one before it."}]}, {"title": "Fetching data", "keywords": ["fetch", "json", "async", "await", "promise", "loading", "error", "search", "filter", "api"], "steps": [{"type": "concept", "heading": "fetch, await, JSON", "body": "fetch requests a URL and returns a promise for the response. await pauses an async function until it settles. response.ok is true for status 200 to 299; response.json() parses the body.", "code": "async function load() {\n  const res = await fetch(\"data.json\");\n  if (!res.ok) throw new Error(\"HTTP \" + res.status);\n  return res.json();\n}"}, {"type": "mcq", "prompt": "What does response.ok tell you?", "options": ["The network is online", "The status code is in the 200 to 299 range", "The JSON is valid", "The request was cached"], "answer": 1, "explain": "fetch only rejects on network failure. A 404 still resolves, so you must check ok yourself."}, {"type": "code", "prompt": "Write async loadProjects(fetchFn). Call fetchFn(\"data.json\"). If the response is ok, return { status: \"ok\", items: <parsed json> }. If it is not ok, or anything throws, return { status: \"error\", items: [] }.", "starter": "async function loadProjects(fetchFn) {\n  \n}", "tests": [{"call": "loadProjects(async () => ({ ok: true, json: async () => [{ title: \"A\" }] }))", "expect": {"status": "ok", "items": [{"title": "A"}]}}, {"call": "loadProjects(async () => ({ ok: false, status: 404, json: async () => ({}) }))", "expect": {"status": "error", "items": []}}, {"call": "loadProjects(async () => { throw new Error(\"offline\"); })", "expect": {"status": "error", "items": []}}], "solution": "async function loadProjects(fetchFn) {\n  try {\n    const res = await fetchFn(\"data.json\");\n    if (!res.ok) return { status: \"error\", items: [] };\n    return { status: \"ok\", items: await res.json() };\n  } catch (e) {\n    return { status: \"error\", items: [] };\n  }\n}", "explain": "Every fetch has three outcomes: data, a bad status, or no answer at all. Handle all three."}, {"type": "concept", "heading": "Data the page carries", "body": "Your exported site is one file, so there is no data.json next to it yet, and a page opened straight from disk cannot fetch at all. Carry a copy of the data inside the page as a JSON data island: a script tag with type=\"application/json\". Browsers never run it; your code reads it with JSON.parse. Fetch fresh data first, fall back to the island, and show the error only when both fail.", "code": "<script type=\"application/json\" id=\"recipes-data\">\n[{ \"title\": \"Lemon pasta\", \"summary\": \"Ten minutes\" }]\n</script>"}, {"type": "build", "prompt": "Add loading and error states with data that always arrives: an element with class loading, an element with class error and role=\"alert\", a JSON data island (a script with type=\"application/json\" and an id), and a module script that tries fetch( first, falls back to the island with JSON.parse inside catch, hides the loading message, and shows the error only if both fail.", "example": "<p class=\"loading\">Loading recipes...</p>\n<p class=\"error\" role=\"alert\" hidden>Could not load recipes. Try again.</p>\n<script type=\"application/json\" id=\"recipes-data\">\n[{ \"title\": \"Lemon pasta\", \"summary\": \"Ten minutes\" }, { \"title\": \"Tomato soup\", \"summary\": \"One pot\" }]\n</script>\n<script type=\"module\">\n  let recipes = [];\n  try {\n    const res = await fetch(\"data.json\");\n    if (!res.ok) throw new Error(\"HTTP \" + res.status);\n    recipes = await res.json();\n  } catch (e) {\n    try {\n      recipes = JSON.parse(document.getElementById(\"recipes-data\").textContent);\n    } catch (e2) {\n      document.querySelector(\".error\").hidden = false;\n    }\n  }\n  document.querySelector(\".loading\").hidden = true;\n</script>", "explain": "Visitors now know when the page is waiting and when something failed, and the page works on any host, even opened from a file. Upload a real data.json later and the same code uses it.", "checks": [{"sel": ".loading", "exists": true, "label": "An element with class loading"}, {"sel": ".error[role=\"alert\"]", "exists": true, "label": "An .error element with role=\"alert\""}, {"sel": "script[type=\"application/json\"][id]", "exists": true, "label": "A JSON data island: a script with type=\"application/json\" and an id"}, {"htmlContains": "fetch(", "label": "The script calls fetch("}, {"htmlContains": "catch", "label": "The script handles failure with catch"}, {"htmlMatch": "JSON\\.parse\\(", "label": "It falls back to the island with JSON.parse(", "hint": "Inside catch, read the island: JSON.parse(document.getElementById(\"recipes-data\").textContent)."}]}, {"type": "code", "prompt": "Write filterProjects(list, query). Return the items whose title, or any of their tags, contains query, ignoring case and surrounding spaces. An empty query returns the whole list.", "starter": "function filterProjects(list, query) {\n  \n}", "tests": [{"call": "filterProjects([{ title: \"Lemon pasta\", tags: [\"quick\"] }, { title: \"Stew\", tags: [\"slow\"] }], \"PASTA\").length", "expect": 1}, {"call": "filterProjects([{ title: \"Lemon pasta\", tags: [\"quick\"] }, { title: \"Stew\", tags: [\"slow\"] }], \" slow \")[0].title", "expect": "Stew"}, {"call": "filterProjects([{ title: \"A\", tags: [] }, { title: \"B\", tags: [] }], \"\").length", "expect": 2}], "solution": "function filterProjects(list, query) {\n  const q = String(query || \"\").trim().toLowerCase();\n  if (!q) return list;\n  return list.filter((p) => p.title.toLowerCase().includes(q) || (p.tags || []).some((t) => t.toLowerCase().includes(q)));\n}", "explain": "Normalize once, compare everywhere. Search that ignores case and stray spaces feels correct."}, {"type": "build", "prompt": "Add a search box: an input with type=\"search\" and id=\"search\", and a label for it.", "example": "<label for=\"search\">Search projects</label>\n<input id=\"search\" type=\"search\" placeholder=\"pasta, quick...\">", "explain": "Hook it to filterProjects on the input event in your exported site, and the grid filters as people type.", "checks": [{"sel": "input#search[type=\"search\"]", "exists": true, "label": "A search input with id=\"search\""}, {"sel": "label[for=\"search\"]", "exists": true, "label": "A label for the search input"}]}, {"type": "order", "prompt": "Order what happens from a keystroke to new results.", "items": ["The visitor types in the search box", "The input event fires", "Filter the array by the query", "Render the matching cards"], "explain": "The event carries the new value, the data is filtered, and the page re-renders from the result.", "codeItems": false, "orderNote": "Each step uses the result of the one before it."}]}]}, {"title": "Real tooling", "lessons": [{"title": "Build tools: npm and Vite", "keywords": ["npm", "vite", "package", "json", "build", "bundler", "node", "dev", "server", "tooling", "terminal"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A computer you can install software on (Windows, macOS or Linux; a phone or a locked school laptop will not do), Node.js 20 or newer from nodejs.org (the LTS download), and a code editor such as VS Code. Cost: free. From this lesson on, part of the work happens in a terminal outside Prexis, so the next two cards cover the terminal from zero."}, {"type": "concept", "heading": "The terminal in five commands", "body": "Open it: on macOS, Terminal (press Cmd and Space, type Terminal). On Windows, PowerShell or the Terminal app. In VS Code, View, then Terminal. You type a command, press Enter and read the answer. Tab finishes a file name for you, and the up arrow brings back the last command. You only need a handful to start.", "code": "pwd            # where am I?\nls             # what is in this folder? (dir in old Windows cmd)\nmkdir my-site  # make a folder\ncd my-site     # go into it\ncd ..          # go back up one folder"}, {"type": "concept", "heading": "Install Node and check it", "body": "Install the LTS version from nodejs.org, then close the terminal and open a new one. node -v and npm -v should each print a version number, like v20.11.0. npm comes with Node; it downloads the tools a project lists in package.json. If you see command not found, the window was opened before the install; a new window fixes it.", "code": "node -v\nnpm -v"}, {"type": "mcq", "prompt": "You type npm -v and the terminal says command not found, right after installing Node. What is the most likely fix?", "options": ["Reinstall your operating system", "Open a new terminal window, then try again", "Type it in the browser address bar", "Put sudo in front of every command"], "answer": 1, "explain": "A terminal reads the list of installed programs when it opens. A window opened before the install does not know Node exists yet."}, {"type": "concept", "heading": "What the tools do", "body": "npm installs packages listed in package.json. Vite runs a dev server that reloads as you save, and npm run build bundles and minifies everything into a dist folder ready to deploy."}, {"type": "mcq", "prompt": "What is in the dist folder after npm run build?", "options": ["Your original source files", "Optimized files ready to upload to a host", "The node_modules packages", "Your Git history"], "answer": 1, "explain": "dist is the output. You deploy dist; you edit src."}, {"type": "worked", "heading": "Move your site into Vite", "problem": "Your exported index.html and a terminal with Node installed.", "steps": ["npm create vite@latest my-site -- --template vanilla, then cd my-site and npm install.", "Replace the generated index.html body with yours. Move the CSS from the style tag into src/style.css.", "In src/main.js add import \"./style.css\"; and keep a script tag: <script type=\"module\" src=\"/src/main.js\"></script>", "npm run dev to work locally, npm run build to produce dist."], "takeaway": "Same HTML and CSS, now with a dev server, imports, and an optimized build.", "code": "npm create vite@latest my-site -- --template vanilla\ncd my-site\nnpm install\nnpm run dev"}, {"type": "order", "prompt": "Order the commands for a fresh clone of a Vite project.", "items": ["npm install", "npm run dev", "npm run build", "npm run preview"], "explain": "Install dependencies, develop, build the output, then preview the built output before deploying.", "codeItems": true, "orderNote": "Order matters: preview serves what build produced, and nothing runs before install."}, {"type": "mcq", "prompt": "Why should node_modules stay out of Git?", "options": ["It is secret", "npm install rebuilds it from package.json and the lockfile, and it is huge", "Git cannot store JavaScript", "Vite deletes it"], "answer": 1, "explain": "Commit package.json and package-lock.json; anyone can recreate node_modules exactly from those."}, {"type": "build", "prompt": "Point your page at a Vite entry: add <script type=\"module\" src=\"/src/main.js\"></script> to your HTML, then set up the project outside Prexis and confirm each part. main.js lives in your Vite project, not in the Workshop, so the Workshop lists it under files your export does not include. That is expected: your Vite build is now the real site.", "example": "<script type=\"module\" src=\"/src/main.js\"></script>\n\n// package.json\n\"scripts\": { \"dev\": \"vite\", \"build\": \"vite build\", \"preview\": \"vite preview\" }\n\n# .gitignore\nnode_modules\ndist", "explain": "Your site has a real toolchain. The same page, now built the way production sites are built.", "checks": [{"sel": "script[type=\"module\"][src*=\"main\"]", "exists": true, "label": "A module script pointing at your main.js entry"}, {"confirm": true, "label": "node -v prints version 20 or newer in my terminal"}, {"confirm": true, "label": "package.json has dev and build scripts"}, {"confirm": true, "label": ".gitignore lists node_modules and dist"}, {"confirm": true, "label": "npm run build produced a dist folder"}]}]}, {"title": "Deploy from Git", "keywords": ["deploy", "continuous", "netlify", "vercel", "preview", "build", "ship", "pull", "request"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Your site in a GitHub repo (from Git and GitHub for real) and a free Netlify or Vercel account that you sign in to with GitHub. Cost: free on the hobby plans."}, {"type": "concept", "heading": "Push to deploy", "body": "Connect your GitHub repo to Netlify or Vercel once. After that, every push to main builds and publishes the site, and every pull request gets its own preview URL. No more dragging folders."}, {"type": "worked", "heading": "Connect the repo", "problem": "Your Vite site is on GitHub. Make Netlify or Vercel build it on every push.", "steps": ["Netlify: Add new site, Import an existing project, pick GitHub and your repo.", "Build command: npm run build. Publish directory: dist. Deploy.", "Vercel: Add New, Project, import the repo. It detects Vite and fills in npm run build and dist.", "Commit the settings as a file so they live with the code: netlify.toml or vercel.json."], "takeaway": "Settings in a file are reviewed, versioned, and survive changing hosts.", "code": "# netlify.toml\n[build]\n  command = \"npm run build\"\n  publish = \"dist\""}, {"type": "mcq", "prompt": "For a Vite site, which folder should the host publish?", "options": ["src", "public", "dist", "node_modules"], "answer": 2, "explain": "Vite builds into dist. Publishing src would serve unbuilt files."}, {"type": "build", "prompt": "Link your live site from the page footer over https, then connect the repo to your host and confirm the setup.", "example": "<footer>\n  <p>Live at <a href=\"https://my-site.netlify.app\">my-site.netlify.app</a></p>\n</footer>\n\n# netlify.toml\n[build]\n  command = \"npm run build\"\n  publish = \"dist\"", "explain": "Every push now ships itself. Your job becomes writing the change; the host does the rest.", "checks": [{"sel": "footer a[href^=\"https://\"]", "exists": true, "label": "A footer link to your live site over https"}, {"confirm": true, "label": "netlify.toml or vercel.json sets npm run build and dist"}, {"confirm": true, "label": "A push to main triggered a deploy that succeeded"}, {"url": "liveUrl", "label": "Your live site address", "kind": "site"}]}, {"type": "concept", "heading": "Preview deploys", "body": "Open a pull request and the host comments with a preview URL built from that branch. Click through it before merging. Problems show up on the preview, not on your real site."}, {"type": "order", "prompt": "Order a change from branch to live.", "items": ["Create a branch", "Commit and push it", "Open a pull request", "Check the preview deploy", "Merge into main", "Watch the production deploy finish"], "explain": "The preview is the safety net between a branch and your visitors.", "codeItems": false, "orderNote": "Order matters: the preview only exists after the pull request, and production only updates after the merge."}, {"type": "mcq", "prompt": "A deploy failed. Where do you look first?", "options": ["The build log on the host", "Your DNS settings", "The browser cache", "The domain registrar"], "answer": 0, "explain": "The log shows the exact command and error. Most failures are a missing package or a typo the build caught."}]}, {"title": "Custom domain and HTTPS", "keywords": ["domain", "dns", "https", "certificate", "cname", "records", "canonical", "registrar", "ssl"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A domain name from a registrar such as Cloudflare, Porkbun or Namecheap, about 10 to 20 dollars a year. This is the only paid step in the course, and it is optional: you can pass this lesson without buying one, and come back when you are ready."}, {"type": "concept", "heading": "Domains in one minute", "body": "A registrar rents you a name like casaverde.com for about 10 to 20 dollars a year. DNS is the phone book that maps the name to your host. The theory is in Websites that work, lesson Domains, hosting, going live. Here you do it."}, {"type": "concept", "heading": "The records you will add", "body": "A record: points the bare domain (casaverde.com) at an IP address. CNAME: points a name like www at another name, such as your-site.netlify.app. TXT: proves to the host that you own the domain. Your host's domain settings page tells you exactly which values to enter."}, {"type": "mcq", "prompt": "Which record usually points www.casaverde.com at your host?", "options": ["TXT", "MX", "CNAME", "AAAA"], "answer": 2, "explain": "CNAME aliases one name to another. MX is for email, TXT is for verification."}, {"type": "order", "prompt": "Put a custom domain live.", "items": ["Buy the domain at a registrar", "Add the domain in your host's settings", "Add the DNS records the host shows you", "Wait for DNS to spread (minutes to hours)", "Confirm the certificate and force HTTPS"], "explain": "The host has to know the domain before it can tell you the records, and the certificate can only be issued once DNS points at the host.", "codeItems": false, "orderNote": "Order matters: each step needs the one before it."}, {"type": "concept", "heading": "HTTPS is free now", "body": "GitHub Pages, Netlify and Vercel issue certificates automatically once DNS points at them. Turn on Force HTTPS, pick one main address (with or without www), and redirect the other to it so search engines see one site."}, {"type": "build", "prompt": "Make the page domain-ready: add a canonical link with an https URL, make sure og:image uses https, and remove any http:// links or images. Paste your domain if you set one up.", "example": "<link rel=\"canonical\" href=\"https://casaverde.com/\">\n<meta property=\"og:image\" content=\"https://casaverde.com/share.png\">", "explain": "One canonical https address, no insecure leftovers. Browsers show the lock and search engines index one site.", "checks": [{"sel": "link[rel=\"canonical\"]", "attr": "href", "label": "A canonical link using https", "contains": "https://"}, {"sel": "meta[property=\"og:image\"]", "attr": "content", "label": "og:image uses https", "contains": "https://"}, {"sel": "a[href^=\"http:\"], img[src^=\"http:\"], link[href^=\"http:\"]", "none": true, "label": "No http:// links, images or stylesheets"}, {"url": "domainUrl", "label": "Your custom domain (optional)", "optional": true, "kind": "domain"}]}, {"type": "mcq", "prompt": "After setup, the browser says Not secure on your domain. What is the likely cause?", "options": ["The domain is too long", "Mixed content (an http:// image or script), or the certificate is still being issued", "You used a CNAME", "Your CSS has errors"], "answer": 1, "explain": "One insecure resource drops the lock. If there is none, wait for the certificate and reload."}]}]}, {"title": "Professional quality", "lessons": [{"title": "Performance", "keywords": ["performance", "speed", "lighthouse", "web", "vitals", "lcp", "cls", "inp", "preload", "lazy", "fonts"], "steps": [{"type": "concept", "heading": "What gets measured", "body": "Lighthouse in Chrome DevTools scores a page. Core Web Vitals are the three numbers Google uses: LCP, how fast the main content appears; CLS, how much the layout jumps; INP, how fast the page responds to a tap or click."}, {"type": "mcq", "prompt": "Which change most often fixes a slow LCP?", "options": ["Minifying the HTML", "A smaller, properly sized hero image that loads first", "Adding more fonts", "Moving the footer"], "answer": 1, "explain": "The largest element is usually the hero image. Shrink it and tell the browser it matters."}, {"type": "concept", "heading": "Tell the browser what matters", "body": "fetchpriority=\"high\" on the hero image moves it to the front of the queue. link rel=\"preload\" starts a key font or image early. font-display: swap shows text in a fallback font instead of hiding it. loading=\"lazy\" defers images below the fold."}, {"type": "build", "prompt": "Speed up the page: give your hero img fetchpriority=\"high\", lazy-load an image lower down, add a link rel=\"preload\", and use font-display: swap in an @font-face rule.", "example": "<link rel=\"preload\" as=\"image\" href=\"https://picsum.photos/id/292/800/450\">\n<img src=\"https://picsum.photos/id/292/800/450\" fetchpriority=\"high\" width=\"800\" height=\"450\" alt=\"Ingredients on a table\">\n<img src=\"https://picsum.photos/id/429/600/400\" loading=\"lazy\" width=\"600\" height=\"400\" alt=\"A finished dish\">\n\n@font-face {\n  font-family: \"Body\";\n  src: local(\"Georgia\");\n  font-display: swap;\n}", "explain": "The important image arrives first, text never hides, and the rest waits its turn.", "checks": [{"sel": "img[fetchpriority=\"high\"]", "exists": true, "label": "A hero img with fetchpriority=\"high\""}, {"sel": "img[loading=\"lazy\"]", "exists": true, "label": "A lazy-loaded image"}, {"sel": "link[rel=\"preload\"]", "exists": true, "label": "A link rel=\"preload\""}, {"cssContains": "font-display", "label": "An @font-face with font-display"}]}, {"type": "code", "prompt": "Write overBudget(assets, limitKb). assets is an array of { name, kb }. Return the total kb when it is over limitKb, otherwise return 0.", "starter": "function overBudget(assets, limitKb) {\n  \n}", "tests": [{"call": "overBudget([{ name: \"hero.jpg\", kb: 300 }, { name: \"app.js\", kb: 120 }], 400)", "expect": 420}, {"call": "overBudget([{ name: \"hero.webp\", kb: 90 }, { name: \"app.js\", kb: 120 }], 400)", "expect": 0}, {"call": "overBudget([], 100)", "expect": 0}], "solution": "function overBudget(assets, limitKb) {\n  const total = assets.reduce((s, a) => s + a.kb, 0);\n  return total > limitKb ? total : 0;\n}", "explain": "A weight budget turns speed into a number a build can check, so the site stays fast after the first cleanup."}, {"type": "order", "prompt": "Run a performance pass.", "items": ["Run Lighthouse on a mobile profile", "Find the biggest issue it reports", "Fix that one thing", "Run Lighthouse again and compare"], "explain": "Measure, fix one thing, measure again. Fixing many things at once hides which one helped.", "codeItems": false, "orderNote": "Order matters: you cannot compare without a first measurement."}, {"type": "mcq", "prompt": "Which metric measures the layout jumping around while the page loads?", "options": ["LCP", "INP", "CLS", "TTFB"], "answer": 2, "explain": "Cumulative Layout Shift. Width and height on images and reserved space for ads keep it low."}]}, {"title": "Accessibility deep dive", "keywords": ["accessibility", "aria", "dialog", "modal", "focus", "skip", "link", "keyboard", "screen", "reader"], "steps": [{"type": "concept", "heading": "The first rule of ARIA", "body": "If a native element does the job, use it. button, a, dialog, details and select come with keyboard support and the right roles. ARIA adds meaning to custom widgets, but it never adds behavior; you would have to write that yourself."}, {"type": "concept", "heading": "dialog does the hard parts", "body": "dialog.showModal() opens a modal that traps focus, makes the rest of the page inert, and closes on Escape. Your job: a close button inside, and focus back on the button that opened it.", "code": "const dlg = document.querySelector(\"dialog\");\nopenBtn.addEventListener(\"click\", () => dlg.showModal());\ndlg.addEventListener(\"close\", () => openBtn.focus());"}, {"type": "build", "prompt": "Add an accessible project modal: a dialog element with a close button inside, and a script that opens it with showModal and returns focus with .focus() when it closes.", "example": "<button class=\"open-details\">Details</button>\n<dialog aria-labelledby=\"dlg-title\">\n  <h2 id=\"dlg-title\">Lemon pasta</h2>\n  <p>Ten minutes, one pan.</p>\n  <form method=\"dialog\"><button>Close</button></form>\n</dialog>\n<script type=\"module\">\n  const dlg = document.querySelector(\"dialog\");\n  const opener = document.querySelector(\".open-details\");\n  opener.addEventListener(\"click\", () => dlg.showModal());\n  dlg.addEventListener(\"close\", () => opener.focus());\n</script>", "explain": "Keyboard users can open, use and close it, and they land back where they started.", "checks": [{"sel": "dialog", "exists": true, "label": "A dialog element"}, {"sel": "dialog button", "exists": true, "label": "A close button inside the dialog"}, {"htmlContains": "showModal", "label": "The script opens it with showModal"}, {"htmlContains": ".focus()", "label": "Focus returns with .focus()"}]}, {"type": "mcq", "prompt": "Which element gives you keyboard support for free?", "options": ["<div onclick>", "<span role=\"button\">", "<button>", "<a> without href"], "answer": 2, "explain": "button is focusable and fires click on Enter and Space. An a without href is not even focusable."}, {"type": "build", "prompt": "Add a skip link: an a with class skip-link and href=\"#main\" at the very top of your HTML, id=\"main\" on your main element (you added main in Semantic HTML, SEO, and sharing; wrap your content in one if you have none), and CSS that shows the link on :focus.", "example": "<a class=\"skip-link\" href=\"#main\">Skip to content</a>\n...\n<main id=\"main\">...</main>\n\n.skip-link { position: absolute; left: -999px; }\n.skip-link:focus { left: 8px; top: 8px; }", "explain": "Keyboard users skip the nav in one keystroke instead of tabbing through every link on every page.", "checks": [{"sel": "a.skip-link[href=\"#main\"]", "exists": true, "label": "A skip link pointing at #main"}, {"sel": "main#main", "exists": true, "label": "A main element with id=\"main\"", "hint": "Add the id to the main you already have: <main id=\"main\">."}, {"cssContains": ".skip-link:focus", "label": "The skip link appears on :focus"}]}, {"type": "order", "prompt": "Run a quick screen reader test.", "items": ["Turn on the screen reader (VoiceOver or NVDA)", "Jump through the headings", "Jump through the landmarks", "Tab through every control and listen to its name", "Open and close the modal"], "explain": "Start it, then check structure, then interaction.", "codeItems": false, "groups": [[1, 2], [3, 4]], "orderNote": "Headings and landmarks can go in either order, and so can the last two checks."}, {"type": "mcq", "prompt": "A custom dropdown cannot be opened with the keyboard. What is the best fix?", "options": ["Add aria-label", "Add tabindex=\"5\"", "Use a native select, or rebuild it on a button with proper keyboard handling", "Hide it from screen readers"], "answer": 2, "explain": "Native elements first. A custom widget needs focus, keys and roles all done by hand."}]}, {"title": "Checks that run themselves: linting and CI", "keywords": ["ci", "github", "actions", "lint", "eslint", "prettier", "workflow", "pipeline", "branch", "protection", "capstone"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Your GitHub repo and the Vite project from earlier lessons. GitHub Actions is free for public repos and includes free monthly minutes for private ones. Cost: free."}, {"type": "concept", "heading": "Machines catch the boring mistakes", "body": "A linter (ESLint) flags likely bugs. A formatter (Prettier) settles style arguments. Continuous integration runs them, plus your build, on every pull request, so a broken change cannot slip in."}, {"type": "worked", "heading": "A GitHub Actions workflow", "problem": "Run lint and build on every pull request.", "steps": ["Create .github/workflows/ci.yml in your repo.", "on: pull_request means it runs for every PR; push to main covers direct pushes.", "Steps check out the code, set up Node, install with npm ci, then run lint and build.", "A red X on the PR means a step failed. Click it to read the log."], "takeaway": "If it would break the build, it breaks the PR first.", "code": "name: ci\non: [pull_request]\njobs:\n  check:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run build"}, {"type": "order", "prompt": "Order the pipeline.", "items": ["Check out the code", "Install with npm ci", "Lint", "Build", "Deploy"], "explain": "Nothing runs without the code, nothing builds without packages, and nothing should deploy that failed a check.", "codeItems": false, "groups": [[2, 3]], "orderNote": "Lint and build can swap; deploy always goes last."}, {"type": "mcq", "prompt": "CI fails on your pull request, but the change looks fine to you. Should you merge?", "options": ["Yes, CI is often wrong", "No. Read the log, fix the cause, and push again", "Yes, then fix it on main", "Delete the workflow"], "answer": 1, "explain": "A red check is information. Merging past it trains everyone to ignore it."}, {"type": "concept", "heading": "Branch protection", "body": "In Settings, Branches, add a rule for main: require a pull request and require the ci check to pass. Now nobody, including you, can push broken code straight to production."}, {"type": "build", "prompt": "Advanced capstone. Your page should show everything from this level: a module script, loading and error states, a search input, an accessible dialog, a skip link, @layer and @container in your CSS, and a canonical https link. Confirm the tooling outside Prexis and paste a passing CI run.", "example": "Use your work from lessons 1 to 8. Nothing new to write here; this step checks it all at once.", "explain": "A data-driven site on a real toolchain, deployed from Git, on your domain, guarded by CI. That is how professional sites run.", "checks": [{"sel": "script[type=\"module\"]", "exists": true, "label": "A module script"}, {"sel": ".loading", "exists": true, "label": "A loading state"}, {"sel": ".error[role=\"alert\"]", "exists": true, "label": "An error state with role=\"alert\""}, {"sel": "input[type=\"search\"]", "exists": true, "label": "A search input"}, {"sel": "dialog button", "exists": true, "label": "An accessible dialog with a close button"}, {"sel": "a[href=\"#main\"]", "exists": true, "label": "A skip link"}, {"cssContains": "@layer", "label": "@layer in your CSS"}, {"cssContains": "@container", "label": "@container in your CSS"}, {"sel": "link[rel=\"canonical\"]", "attr": "href", "label": "A canonical https link", "contains": "https://"}, {"confirm": true, "label": "package.json has dev, build and lint scripts"}, {"confirm": true, "label": ".github/workflows/ci.yml runs lint and build on pull_request"}, {"url": "ciUrl", "label": "A link to a passing CI run on GitHub", "kind": "ci"}]}]}]}]}, {"id": "web-expert", "subject": "Web engineering", "level": "Expert", "title": "Shipping real web apps", "track": "web", "prereq": "web-advanced", "rev": "2026-09-30", "unlock": {"after": "web-advanced", "mastery": 85, "skill": "Web apps"}, "blurb": "TypeScript, components, routing, APIs, databases and sign in, security, testing, production.", "units": [{"title": "Typed components", "lessons": [{"title": "TypeScript for the web", "keywords": ["typescript", "types", "interface", "jsdoc", "ts-check", "tsconfig", "strict", "type"], "steps": [{"type": "concept", "heading": "How the Expert level works", "body": "The real app now lives in a project on your computer, built with the Node, npm and Vite you set up in the Advanced level. Every lesson has the same three parts. The page in Prexis grows the parts a browser can show. A code step runs the core logic for real, so you know it works. A worked example walks you through the part that happens in your project, and self checks track it on your honor. If a step feels like a jump, do the worked example in your project first, then come back."}, {"type": "concept", "heading": "Before you start: what you need", "body": "Node 20 or newer, a terminal and a code editor (VS Code checks TypeScript as you type). Cost: free."}, {"type": "worked", "heading": "Start the Expert project once", "problem": "Make a TypeScript and React project you will grow through this level.", "steps": ["In a terminal: npm create vite@latest casa-app -- --template react-ts, then cd casa-app and npm install.", "npm run dev prints a local address. Open it, edit src/App.tsx, save, and watch the page update.", "Copy your Workshop page into index.html and your CSS into src/index.css, so both versions match.", "git init, commit, and push it to a new GitHub repo. Every later lesson adds to this project."], "takeaway": "One project, set up once. The rest of the level fills it in.", "code": "npm create vite@latest casa-app -- --template react-ts\ncd casa-app\nnpm install\nnpm run dev"}, {"type": "concept", "heading": "Types catch bugs before the browser does", "body": "TypeScript is JavaScript plus type annotations. The compiler checks them and then strips them, so the browser still runs plain JavaScript. You can start without a build step: add // @ts-check to a JS file and describe types in JSDoc comments; VS Code checks them as you type.", "code": "// @ts-check\n/** @typedef {{ title: string, tags: string[] }} Project */\n/** @param {Project} p */\nfunction renderCard(p) { return p.title; }"}, {"type": "mcq", "prompt": "A type error at build time saves you from what?", "options": ["Slower page loads", "A crash in a visitor's browser, like reading .length of undefined", "Bad SEO", "Merge conflicts"], "answer": 1, "explain": "The same mistake either shows up on your screen during the build, or on a visitor's screen in production."}, {"type": "concept", "heading": "Unknown data needs a guard", "body": "Data from fetch has no guaranteed shape. Type it as unknown, then write a type guard: a function that checks the shape at runtime and tells the compiler what it proved.", "code": "function isProject(x: unknown): x is Project {\n  return typeof x === \"object\" && x !== null && typeof (x as any).title === \"string\";\n}"}, {"type": "code", "prompt": "Write isProject(x). Return true only when x is a non-null object with a string title and an array tags whose items are all strings.", "starter": "function isProject(x) {\n  \n}", "tests": [{"call": "isProject({ title: \"Stew\", tags: [\"slow\"] })", "expect": true}, {"call": "isProject({ title: \"Stew\" })", "expect": false}, {"call": "isProject(null)", "expect": false}, {"call": "isProject({ title: 7, tags: [] })", "expect": false}, {"call": "isProject({ title: \"A\", tags: [1] })", "expect": false}], "solution": "function isProject(x) {\n  return typeof x === \"object\" && x !== null && typeof x.title === \"string\" && Array.isArray(x.tags) && x.tags.every((t) => typeof t === \"string\");\n}", "explain": "Check at the boundary once, then the rest of your code can trust the type."}, {"type": "build", "prompt": "Type your page script without a build: in a module script, add // @ts-check, a @typedef for Project, and a @param on renderCard.", "example": "<script type=\"module\">\n  // @ts-check\n  /** @typedef {{ title: string, summary: string }} Project */\n  /** @param {Project} p */\n  const renderCard = (p) => `<article class=\"card\"><h3 class=\"card__title\">${p.title}</h3><p>${p.summary}</p></article>`;\n</script>", "explain": "Your editor now flags a typo like p.tittle before you ever load the page. The next step is real .ts files with tsconfig strict.", "checks": [{"sel": "script[type=\"module\"]", "exists": true, "label": "A module script"}, {"htmlContains": "@ts-check", "label": "The script opts in with // @ts-check", "raw": true}, {"htmlContains": "@typedef", "label": "A @typedef describes Project", "raw": true}, {"htmlContains": "@param", "label": "renderCard has a typed @param", "raw": true}]}, {"type": "mcq", "prompt": "Data from fetch has an unknown shape. What is the safe approach?", "options": ["Cast it with as Project and move on", "Validate it with a type guard or schema, then use the typed value", "Turn off strict mode", "Use any everywhere"], "answer": 1, "explain": "A cast is a promise you cannot keep. A guard is a check you actually run."}, {"type": "order", "prompt": "Migrate one file to TypeScript.", "items": ["Add tsconfig.json with strict set to true", "Rename one file from .js to .ts", "Fix the errors the compiler reports", "Run tsc --noEmit in CI so it stays fixed"], "explain": "Config first so the rules apply, then one file at a time, then lock it in with CI.", "codeItems": false, "orderNote": "Order matters: the compiler needs its config before it can report errors."}]}, {"title": "A component framework", "keywords": ["react", "framework", "components", "props", "state", "usestate", "keys", "reducer", "jsx"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "The Vite project from TypeScript for the web, with React (it came with the react-ts template). For the page in Prexis you can also load React from https://esm.sh, a free public CDN, so the exported page runs it with no build. Cost: free."}, {"type": "concept", "heading": "Components are functions", "body": "A component takes props and returns UI. React, Vue and Svelte all share the idea; React is the most common, so the examples use it. Your renderCard was already a component without the name.", "code": "function Card({ title, summary }) {\n  return <article className=\"card\"><h3>{title}</h3><p>{summary}</p></article>;\n}"}, {"type": "concept", "heading": "State and keys", "body": "State is data that changes while the page is open, like a search query. When it changes, React re-runs the component and updates only what differs. In lists, each item needs a stable key so React can tell which one moved.", "code": "const [query, setQuery] = useState(\"\");\nprojects.filter(match(query)).map((p) => <Card key={p.id} {...p} />)"}, {"type": "mcq", "prompt": "Why does each item in a rendered list need a key?", "options": ["It sets the CSS class", "React uses it to match items between renders, so state and focus stay with the right item", "It sorts the list", "It is only needed on servers"], "answer": 1, "explain": "Without stable keys, deleting the first item can shift every input's state to the wrong card."}, {"type": "code", "prompt": "State updates should not mutate. Write reducer(state, action) for { query, tags }. On { type: \"query\", value } return a new state with query set. On { type: \"toggleTag\", tag } add the tag if missing or remove it if present. Return state unchanged for anything else.", "starter": "function reducer(state, action) {\n  \n}", "tests": [{"call": "reducer({ query: \"\", tags: [] }, { type: \"query\", value: \"pasta\" })", "expect": {"query": "pasta", "tags": []}}, {"call": "reducer({ query: \"\", tags: [\"quick\"] }, { type: \"toggleTag\", tag: \"vegan\" })", "expect": {"query": "", "tags": ["quick", "vegan"]}}, {"call": "reducer({ query: \"\", tags: [\"quick\", \"vegan\"] }, { type: \"toggleTag\", tag: \"quick\" })", "expect": {"query": "", "tags": ["vegan"]}}, {"call": "(() => { const s = { query: \"a\", tags: [] }; reducer(s, { type: \"query\", value: \"b\" }); return s.query; })()", "expect": "a"}], "solution": "function reducer(state, action) {\n  if (action.type === \"query\") return { ...state, query: action.value };\n  if (action.type === \"toggleTag\") {\n    const has = state.tags.includes(action.tag);\n    return { ...state, tags: has ? state.tags.filter((t) => t !== action.tag) : [...state.tags, action.tag] };\n  }\n  return state;\n}", "explain": "Return new objects instead of editing old ones. That is how React notices a change."}, {"type": "build", "prompt": "Mark the island your framework will own: a div with id=\"cards-root\" holding three static .card fallbacks, and a module script with a real component that keeps state with useState and gives each card a key. Import React from https://esm.sh so the exported page runs it, as in the example. Comments do not count; the check reads your code.", "example": "<div id=\"cards-root\">\n  <article class=\"card\"><h3>Lemon pasta</h3></article>\n  <article class=\"card\"><h3>Tomato soup</h3></article>\n  <article class=\"card\"><h3>Green salad</h3></article>\n</div>\n<script type=\"module\">\n  import { createElement as h, useState } from \"https://esm.sh/react@18\";\n  import { createRoot } from \"https://esm.sh/react-dom@18/client\";\n  const recipes = [\n    { id: 1, title: \"Lemon pasta\" },\n    { id: 2, title: \"Tomato soup\" },\n    { id: 3, title: \"Green salad\" },\n  ];\n  function CardGrid() {\n    const [query, setQuery] = useState(\"\");\n    const shown = recipes.filter((r) => r.title.toLowerCase().includes(query.toLowerCase()));\n    return h(\"div\", null,\n      h(\"input\", { type: \"search\", \"aria-label\": \"Filter recipes\", value: query, onChange: (e) => setQuery(e.target.value) }),\n      shown.map((r) => h(\"article\", { key: r.id, className: \"card\" }, h(\"h3\", null, r.title))));\n  }\n  createRoot(document.getElementById(\"cards-root\")).render(h(CardGrid));\n</script>\n\nIn your Vite + React project the same component is JSX in src/CardGrid.jsx:\n  shown.map((r) => <Card key={r.id} {...r} />)", "explain": "The static cards keep the page useful before JavaScript loads; React takes over #cards-root when it does. Export it and type in the filter box to watch state at work.", "checks": [{"sel": "#cards-root", "exists": true, "label": "A mount point with id=\"cards-root\""}, {"sel": "#cards-root .card", "count": 3, "label": "Three fallback cards inside it"}, {"htmlMatch": "\\buseState\\s*\\(", "label": "The component calls useState( in code, not in a comment", "hint": "Write the component for real, like the example. Lines inside // or /* */ comments are ignored."}, {"htmlMatch": "\\bkey\\s*[:=]\\s*[{\\w\\\"']", "label": "Each rendered card gets a key in code", "hint": "Pass a key when you map: h(\"article\", { key: r.id }, ...) or <Card key={r.id} /> in JSX."}]}, {"type": "order", "prompt": "Order what happens when state changes.", "items": ["The visitor types in the search box", "onChange calls setQuery", "React re-runs the component with the new state", "React compares the new output to the old", "Only the changed DOM nodes update"], "explain": "Event, state update, re-render, diff, patch. You write the first two; React does the rest.", "codeItems": false, "orderNote": "Each step triggers the next."}, {"type": "mcq", "prompt": "When is plain HTML and CSS a better choice than a framework?", "options": ["Never", "A mostly static content site with a little interactivity", "Any site with a form", "Any site with more than one page"], "answer": 1, "explain": "Frameworks pay off with lots of changing state. For a brochure site they add weight and nothing else."}]}, {"title": "Routing and app structure", "keywords": ["routing", "router", "spa", "routes", "history", "hash", "404", "layout", "next"], "steps": [{"type": "concept", "heading": "Pages or routes", "body": "Separate HTML files are the simplest router there is. A single page app swaps views in JavaScript and updates the URL with history.pushState or the hash. Meta frameworks like Next.js or Astro generate routes from folders and can render on the server."}, {"type": "mcq", "prompt": "What does a 404 route handle?", "options": ["Server crashes", "Any URL that matches no other route", "Slow pages", "Signed out users"], "answer": 1, "explain": "Every router needs a catch-all, or unknown URLs show a blank screen instead of a helpful page."}, {"type": "code", "prompt": "Write matchRoute(path) for the routes \"/\", \"/projects\" and \"/projects/:id\". Return { name, params }: names are \"home\", \"projects\", \"project\" (with params.id), and \"notFound\" with empty params for anything else. Ignore one trailing slash.", "starter": "function matchRoute(path) {\n  \n}", "tests": [{"call": "matchRoute(\"/\")", "expect": {"name": "home", "params": {}}}, {"call": "matchRoute(\"/projects/\")", "expect": {"name": "projects", "params": {}}}, {"call": "matchRoute(\"/projects/lemon-pasta\")", "expect": {"name": "project", "params": {"id": "lemon-pasta"}}}, {"call": "matchRoute(\"/nope\")", "expect": {"name": "notFound", "params": {}}}], "solution": "function matchRoute(path) {\n  const p = path.length > 1 && path.endsWith(\"/\") ? path.slice(0, -1) : path;\n  if (p === \"/\") return { name: \"home\", params: {} };\n  if (p === \"/projects\") return { name: \"projects\", params: {} };\n  const m = /^\\/projects\\/([^/]+)$/.exec(p);\n  if (m) return { name: \"project\", params: { id: m[1] } };\n  return { name: \"notFound\", params: {} };\n}", "explain": "Every router, from a dozen lines to Next.js, is this: turn a URL into a name and some parameters."}, {"type": "build", "prompt": "Add hash routes to your page: at least two links whose href starts with #/, a section with data-route=\"not-found\" for unknown URLs, and a script that listens for hashchange.", "example": "<nav>\n  <a href=\"#/\">Home</a>\n  <a href=\"#/projects\">Projects</a>\n</nav>\n<section data-route=\"not-found\" hidden>\n  <h2>Page not found</h2>\n  <p><a href=\"#/\">Back home</a></p>\n</section>\n<script type=\"module\">\n  const routes = [\"#/\", \"#/projects\"];\n  function render() {\n    const hash = location.hash || \"#/\";\n    document.querySelector('[data-route=\"not-found\"]').hidden = routes.includes(hash);\n  }\n  window.addEventListener(\"hashchange\", render);\n  render();\n</script>", "explain": "Hash routes work on any static host with no server setup, which makes them a safe first router.", "checks": [{"sel": "a[href^=\"#/\"]", "count": 2, "label": "At least two #/ route links"}, {"sel": "[data-route=\"not-found\"]", "exists": true, "label": "A not-found view"}, {"htmlContains": "hashchange", "label": "The script listens for hashchange"}]}, {"type": "concept", "heading": "A shared layout", "body": "Header, nav and footer render once in a layout; only the inner view changes per route. After each route change, set document.title and move focus to the new heading so screen reader users know the page changed."}, {"type": "order", "prompt": "Order what a client router does when a link is clicked.", "items": ["Intercept the click", "Update the URL with history.pushState", "Match the URL to a route", "Render that view inside the layout", "Update document.title and move focus to the new heading"], "explain": "The URL changes first so back and forward work, then the view, then the announcements.", "codeItems": false, "orderNote": "Order matters: rendering needs the matched route, and focus needs the rendered heading."}, {"type": "mcq", "prompt": "After a client route change, screen reader users hear nothing. What fixes it?", "options": ["Reload the page", "Move focus to the new view's heading and update document.title", "Add more ARIA labels to the nav", "Use a slower transition"], "answer": 1, "explain": "A full page load announces itself. A JavaScript view swap has to announce itself on purpose."}]}]}, {"title": "Backend", "lessons": [{"title": "Your own API", "keywords": ["api", "serverless", "functions", "http", "status", "codes", "rest", "env", "secrets", "backend"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free Netlify or Vercel account to run serverless functions (the free tiers cover a small site), and Node to test the function locally with netlify dev or vercel dev. Cost: free."}, {"type": "concept", "heading": "An API is a URL that returns data", "body": "GET reads, POST creates, PUT or PATCH updates, DELETE removes. Status codes report the result: 200 OK, 201 Created, 400 bad input, 401 not signed in, 404 not found, 405 wrong method, 500 server error."}, {"type": "mcq", "prompt": "Which status code means a new item was created?", "options": ["200", "201", "204", "302"], "answer": 1, "explain": "201 Created. 200 is a general success, 204 is success with no body."}, {"type": "concept", "heading": "Serverless functions", "body": "Netlify and Vercel run a function file when its URL is requested. No server to manage, and small sites stay on the free tier. On Vercel, api/recipes.js answers /api/recipes; name the file after your data.", "code": "export default function handler(req, res) {\n  if (req.method !== \"GET\") return res.status(405).json({ error: \"Method not allowed\" });\n  res.status(200).json(projects);\n}"}, {"type": "code", "prompt": "Write handle(req, projects). For method \"GET\" return { status: 200, body: projects }. For any other method return { status: 405, body: { error: \"Method not allowed\" } }.", "starter": "function handle(req, projects) {\n  \n}", "tests": [{"call": "handle({ method: \"GET\" }, [{ id: 1 }])", "expect": {"status": 200, "body": [{"id": 1}]}}, {"call": "handle({ method: \"DELETE\" }, [])", "expect": {"status": 405, "body": {"error": "Method not allowed"}}}, {"call": "handle({ method: \"POST\" }, []).status", "expect": 405}], "solution": "function handle(req, projects) {\n  if (req.method === \"GET\") return { status: 200, body: projects };\n  return { status: 405, body: { error: \"Method not allowed\" } };\n}", "explain": "Pure request in, response out. Keeping the logic in a plain function also makes it easy to test."}, {"type": "concept", "heading": "Secrets stay on the server", "body": "API keys go in environment variables on the host, read with process.env.NAME inside the function. Anything in your page's JavaScript is public. Commit a .env.example with empty values, and list .env in .gitignore."}, {"type": "build", "prompt": "Point the front end at your API: a module script that fetches one of your own routes (any /api/ path, such as /api/recipes or /api/projects), and a new message with id=\"api-error\" and role=\"alert\" that the script shows when the request fails. Then build the function outside Prexis and confirm it.", "example": "<p id=\"api-error\" role=\"alert\" hidden>Could not reach the recipe API.</p>\n<script type=\"module\">\n  try {\n    const res = await fetch(\"/api/recipes\");\n    if (!res.ok) throw new Error(\"HTTP \" + res.status);\n    const recipes = await res.json();\n  } catch (e) {\n    document.getElementById(\"api-error\").hidden = false;\n  }\n</script>\n\n# .gitignore\n.env", "explain": "Your site now has a backend. The data can change without redeploying the page. Until the function is deployed, the exported page shows your api-error message, which is the point of having one.", "checks": [{"htmlMatch": "fetch\\(\\s*[\\\"'`]/api/[\\w-]+", "label": "The page fetches one of your /api/ routes", "hint": "Name the route after your data, for example fetch(\"/api/recipes\"). Any /api/ path works."}, {"sel": "#api-error[role=\"alert\"]", "exists": true, "label": "A new #api-error message with role=\"alert\"", "hint": "The .error from Fetching data does not count; this message is for API failures. Add <p id=\"api-error\" role=\"alert\" hidden>...</p>."}, {"htmlMatch": "getElementById\\(\\s*[\\\"']api-error[\\\"']|querySelector\\(\\s*[\\\"']#api-error[\\\"']", "label": "The script shows #api-error when the request fails", "hint": "In your catch, set document.getElementById(\"api-error\").hidden = false."}, {"confirm": true, "label": "My api function returns 200 for GET and 405 for other methods"}, {"confirm": true, "label": ".env is in .gitignore and the function reads process.env"}]}, {"type": "order", "prompt": "Order a request from click to cards.", "items": ["The visitor clicks Load projects", "The browser sends GET /api/projects", "The host runs your function", "The function returns JSON with status 200", "The page renders the cards"], "explain": "Browser to host to function and back. Every step is a place a log line can tell you what went wrong.", "codeItems": false, "orderNote": "Each step waits on the one before it."}]}, {"title": "Databases and sign in", "keywords": ["database", "sql", "postgres", "supabase", "auth", "sign", "login", "session", "authorization", "tables"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "A free Supabase or Neon account for the database, and an auth provider (Supabase Auth, Clerk or Auth.js all have free tiers). Cost: free for a small project; paid plans start when you have real traffic."}, {"type": "concept", "heading": "Tables, rows, and when hosted is enough", "body": "A table is a list of rows with fixed columns: projects(id, title, owner_id). Hosted Postgres from Supabase or Neon gives you a real database with a free tier and nothing to maintain. Your API function reads from it instead of data.json."}, {"type": "concept", "heading": "Sign in without storing passwords", "body": "Use an auth provider (Supabase Auth, Clerk, Auth.js) instead of storing passwords yourself. After sign in, the server sets a session cookie. Every protected API call checks that session and answers 401 without one."}, {"type": "mcq", "prompt": "Where must the check \"can this user edit this project?\" happen?", "options": ["In the button's onclick", "On the server, in the API or the database rules", "In CSS", "In localStorage"], "answer": 1, "explain": "Anything in the browser can be edited by the visitor. Only the server's answer counts."}, {"type": "code", "prompt": "Write canEdit(user, project). Return true when user exists and either user.id equals project.ownerId or user.role is \"admin\". Return false otherwise.", "starter": "function canEdit(user, project) {\n  \n}", "tests": [{"call": "canEdit({ id: 1, role: \"user\" }, { ownerId: 1 })", "expect": true}, {"call": "canEdit({ id: 2, role: \"user\" }, { ownerId: 1 })", "expect": false}, {"call": "canEdit({ id: 3, role: \"admin\" }, { ownerId: 1 })", "expect": true}, {"call": "canEdit(null, { ownerId: 1 })", "expect": false}], "solution": "function canEdit(user, project) {\n  if (!user) return false;\n  return user.id === project.ownerId || user.role === \"admin\";\n}", "explain": "Signed out is false first. Then ownership, then roles. Run it on the server for every write."}, {"type": "build", "prompt": "Add sign in to the page: a button with class sign-in, an element marked data-requires-auth for content only signed-in users see, and code that handles a 401 response.", "example": "<button class=\"sign-in\" hidden>Sign in</button>\n<section data-requires-auth hidden>\n  <h2>Your drafts</h2>\n</section>\n<script type=\"module\">\n  try {\n    const res = await fetch(\"/api/drafts\");\n    if (res.status === 401) {\n      document.querySelector(\".sign-in\").hidden = false;\n    } else if (res.ok) {\n      document.querySelector(\"[data-requires-auth]\").hidden = false;\n    }\n  } catch (e) {\n    document.querySelector(\".sign-in\").hidden = false;\n  }\n</script>", "explain": "The page shows what a visitor may see, and the server enforces it.", "checks": [{"sel": "button.sign-in", "exists": true, "label": "A sign-in button"}, {"sel": "[data-requires-auth]", "exists": true, "label": "A section marked data-requires-auth"}, {"htmlMatch": "\\.status\\s*(===?|!==?)\\s*401\\b|\\b401\\s*(===?|!==?)\\s*[\\w.]*status\\b|\\bcase\\s+401\\b", "label": "The script checks the response for status 401", "hint": "Compare the response status, for example: if (res.status === 401) { show the sign-in button }."}]}, {"type": "order", "prompt": "Order the sign in flow.", "items": ["The visitor presses Sign in", "The app redirects to the auth provider", "The visitor proves who they are", "The provider redirects back with a code", "The server swaps the code for a session cookie", "API calls now carry the session"], "explain": "This is the OAuth shape almost every sign in button uses.", "codeItems": false, "orderNote": "Each step needs the result of the one before it."}, {"type": "mcq", "prompt": "A signed-in user can see another user's drafts. What is missing?", "options": ["A prettier login page", "A server-side check that filters by owner, such as row level security", "A longer session", "HTTPS"], "answer": 1, "explain": "Authentication says who you are. Authorization says what you may see, and it has to run on the server."}]}, {"title": "Security for web developers", "keywords": ["security", "xss", "csrf", "injection", "csp", "headers", "escape", "secrets", "dependabot"], "steps": [{"type": "concept", "heading": "The three classics", "body": "XSS: attacker text becomes script on your page. CSRF: another site makes a visitor's browser send a request to yours. Injection: input changes the meaning of a database query. Escaping output, SameSite cookies, and parameterized queries stop most of it."}, {"type": "mcq", "prompt": "Which line has an XSS risk when comment comes from a visitor?", "options": ["el.textContent = comment", "el.innerHTML = comment", "el.setAttribute(\"title\", comment)", "console.log(comment)"], "answer": 1, "explain": "innerHTML parses the string as HTML, so a crafted comment can run script."}, {"type": "code", "prompt": "Write escapeHtml(s). Replace & with &amp;, < with &lt;, > with &gt;, \" with &quot; and ' with &#39;. Do & first.", "starter": "function escapeHtml(s) {\n  \n}", "tests": [{"call": "escapeHtml(\"<b>hi</b>\")", "expect": "&lt;b&gt;hi&lt;/b&gt;"}, {"call": "escapeHtml(\"Tom & Jerry\")", "expect": "Tom &amp; Jerry"}, {"call": "escapeHtml(\"say \\\"hi\\\" it's\")", "expect": "say &quot;hi&quot; it&#39;s"}], "solution": "function escapeHtml(s) {\n  return String(s).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\").replace(/'/g, \"&#39;\");\n}", "explain": "Ampersand first, or you would double-escape the entities you just made."}, {"type": "concept", "heading": "Headers that defend you", "body": "Content-Security-Policy lists where scripts, styles and images may come from, so injected script is blocked. X-Content-Type-Options: nosniff and a Referrer-Policy close smaller holes. Set them in netlify.toml or vercel.json; a meta tag can carry CSP too."}, {"type": "concept", "heading": "A policy that does not lock you out", "body": "default-src 'self' on its own blocks every inline style tag and inline script, and every image from another site. Your exported page is exactly that: one file with an inline style, inline scripts, picsum images and React from esm.sh. So name each kind: style-src and script-src with 'self' and 'unsafe-inline', script-src with any host you import from, and img-src with https: and data:. Once you have a build step, replace 'unsafe-inline' in script-src with nonces or hashes."}, {"type": "build", "prompt": "Harden the page: a meta Content-Security-Policy with default-src plus style-src, script-src and img-src that still allow your own page (its inline style and scripts, your image hosts, and https://esm.sh if you import React from it), a meta referrer policy, and no innerHTML anywhere in your page code. The innerHTML from JavaScript modules and components counts: rebuild those cards with createElement and textContent, as the example shows. Then set the headers on your host.", "example": "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline' https://esm.sh; img-src 'self' https: data:\">\n<meta name=\"referrer\" content=\"strict-origin-when-cross-origin\">\n\nReplace the innerHTML line from JavaScript modules and components:\n  const grid = document.querySelector(\".gallery, .grid\");\n  grid.replaceChildren(...projects.map((p) => {\n    const card = document.createElement(\"article\");\n    card.className = \"card\";\n    const title = document.createElement(\"h3\");\n    title.className = \"card__title\";\n    title.textContent = p.title;\n    card.append(title);\n    return card;\n  }));", "explain": "Export puts these meta tags in the head where browsers enforce them. Your policy allows your own inline style and scripts and nothing you did not name; tighten script-src with nonces once you have a build.", "checks": [{"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "A CSP meta tag with default-src", "contains": "default-src"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "The policy sets style-src", "contains": "style-src"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "The policy sets script-src", "contains": "script-src"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "attr": "content", "label": "The policy sets img-src", "contains": "img-src"}, {"cspOk": true, "label": "The policy still lets your own styles, scripts and images load", "hint": "The lines below say what your policy would block in the exported site. The Workshop shows the same list next to Export my site."}, {"sel": "meta[name=\"referrer\"]", "attr": "content", "label": "A referrer policy"}, {"htmlContains": "innerHTML", "label": "No innerHTML in your page code", "negate": true, "hint": "Look in the module script from JavaScript modules and components: replace the .innerHTML = line with replaceChildren and createElement, as the example shows."}, {"confirm": true, "label": "My host config sends X-Content-Type-Options: nosniff"}]}, {"type": "order", "prompt": "Respond to a leaked API key.", "items": ["Revoke the key at the provider", "Create a new key", "Update the environment variable on the host", "Redeploy", "Review the provider's logs for misuse"], "explain": "Kill it first; every minute it works is a minute it can be used. Deleting the commit does not help, the key is already copied.", "codeItems": false, "orderNote": "Revoke comes first, always."}, {"type": "concept", "heading": "Keep dependencies patched", "body": "Turn on Dependabot alerts and security updates in your repo's Settings. It opens pull requests when a package you use has a known hole, and your CI tells you if the update breaks anything."}]}]}, {"title": "Production", "lessons": [{"title": "Testing at depth", "keywords": ["testing", "tests", "unit", "e2e", "playwright", "vitest", "flaky", "tdd", "ci"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Vitest and Playwright, both free from npm. Playwright downloads its own browsers the first time, about 300 MB. Your CI from Checks that run themselves runs them. Cost: free."}, {"type": "concept", "heading": "Three kinds of tests", "body": "Unit tests check one function, fast. Integration tests check pieces together, like an API with its database. End to end tests drive a real browser through a real flow, like signing in. Many unit tests, a few end to end tests."}, {"type": "mcq", "prompt": "Which test type catches a broken sign in flow?", "options": ["A unit test of a helper", "An end to end test that signs in through the browser", "A lint rule", "A type check"], "answer": 1, "explain": "Sign in crosses the page, the provider and your API. Only a test that drives the whole path sees it break."}, {"type": "code", "prompt": "Red, green: these tests already exist. Write slugify(title) so they pass: lowercase, trim, turn every run of non letters or digits into one hyphen, and drop hyphens at the ends.", "starter": "function slugify(title) {\n  \n}", "tests": [{"call": "slugify(\"Lemon Pasta\")", "expect": "lemon-pasta"}, {"call": "slugify(\"  Fast & Easy!  \")", "expect": "fast-easy"}, {"call": "slugify(\"10 minute meals\")", "expect": "10-minute-meals"}], "solution": "function slugify(title) {\n  return String(title).toLowerCase().trim().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\");\n}", "explain": "The tests defined done before the code existed. That is test driven development in one step."}, {"type": "worked", "heading": "An end to end test with Playwright", "problem": "Check that search filters the cards on the real page.", "steps": ["npm init playwright@latest adds the runner and an example.", "page.goto opens your local build. getByTestId finds elements by data-testid.", "fill types into the search box; expect waits until the visible card count matches.", "npx playwright test runs it locally; the same command runs in CI."], "takeaway": "Stable test ids make tests survive redesigns.", "code": "test(\"search filters cards\", async ({ page }) => {\n  await page.goto(\"/\");\n  await page.getByTestId(\"search\").fill(\"pasta\");\n  await expect(page.getByTestId(\"card\")).toHaveCount(1);\n});"}, {"type": "build", "prompt": "Make the page testable: data-testid=\"search\" on your search input, data-testid=\"card\" on at least three cards, and an email error message with id=\"email-error\" and aria-live. Then add the tests to CI.", "example": "<input id=\"search\" type=\"search\" data-testid=\"search\">\n<article class=\"card\" data-testid=\"card\">...</article>\n<p id=\"email-error\" aria-live=\"polite\"></p>", "explain": "Tests can now find what they need without depending on your class names or layout.", "checks": [{"sel": "[data-testid=\"search\"]", "exists": true, "label": "A search input with data-testid=\"search\""}, {"sel": "[data-testid=\"card\"]", "count": 3, "label": "At least three cards with data-testid=\"card\""}, {"sel": "#email-error[aria-live]", "exists": true, "label": "An email error region with aria-live"}, {"confirm": true, "label": "ci.yml runs npm test on every pull request"}]}, {"type": "order", "prompt": "Order the red, green, refactor loop.", "items": ["Write a failing test", "Run it and watch it fail", "Write the least code that passes", "Run it and watch it pass", "Refactor with the test still green"], "explain": "Watching it fail proves the test can fail. Refactoring last means you change shape with a safety net.", "codeItems": false, "orderNote": "Order matters: that is the whole method."}, {"type": "mcq", "prompt": "A test fails only sometimes. What is it called, and what do you do?", "options": ["A smoke test; delete it", "A flaky test; find the race or shared state and fix it, quarantining it meanwhile", "A unit test; rerun until green", "A regression; revert everything"], "answer": 1, "explain": "Flaky tests teach a team to ignore red. Fix the timing or isolation problem, do not just retry."}]}, {"title": "Running in production", "keywords": ["production", "monitoring", "logs", "errors", "uptime", "health", "rollback", "incident", "analytics"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Optional: a free Sentry account for error tracking and a free uptime checker such as UptimeRobot or Better Stack. The lesson works without them; you send errors to your own /api/log. Cost: free."}, {"type": "concept", "heading": "Know before your users tell you", "body": "Logs show what your functions did. Error tracking (Sentry and similar) collects browser and server errors with stack traces. An uptime check hits a URL every minute. Privacy friendly analytics (Plausible, Fathom) show traffic without tracking people."}, {"type": "mcq", "prompt": "Users report a blank page. Which tool tells you the actual error?", "options": ["Uptime monitoring", "Browser error tracking with stack traces", "Analytics page views", "The DNS dashboard"], "answer": 1, "explain": "Uptime only says the server answered. The blank page is a script error in their browser, which error tracking captures."}, {"type": "code", "prompt": "Write health(checks). checks is an object like { db: true, auth: false }. Return { status: 200, body: { ok: true } } when every value is true, otherwise { status: 503, body: { ok: false, failing: [names of false checks] } }.", "starter": "function health(checks) {\n  \n}", "tests": [{"call": "health({ db: true, auth: true })", "expect": {"status": 200, "body": {"ok": true}}}, {"call": "health({ db: true, auth: false })", "expect": {"status": 503, "body": {"ok": false, "failing": ["auth"]}}}, {"call": "health({})", "expect": {"status": 200, "body": {"ok": true}}}], "solution": "function health(checks) {\n  const failing = Object.keys(checks).filter((k) => !checks[k]);\n  if (!failing.length) return { status: 200, body: { ok: true } };\n  return { status: 503, body: { ok: false, failing } };\n}", "explain": "An uptime check pointed at /api/health now tells you which dependency broke, not just that something did."}, {"type": "build", "prompt": "Catch errors on the page: an element with id=\"app-error\" and role=\"alert\" as a friendly fallback, and a module script that listens for unhandledrejection and sends errors to a trackError( function. Do not call it reportError: browsers already have a built-in window.reportError, and a function with that name replaces it.", "example": "<div id=\"app-error\" role=\"alert\" hidden>Something broke. Reload, or try again in a minute.</div>\n<script type=\"module\">\n  function trackError(e) {\n    navigator.sendBeacon(\"/api/log\", JSON.stringify({ message: String(e) }));\n    document.getElementById(\"app-error\").hidden = false;\n  }\n  window.addEventListener(\"error\", (e) => trackError(e.message));\n  window.addEventListener(\"unhandledrejection\", (e) => trackError(e.reason));\n</script>", "explain": "Visitors see a calm message instead of a blank page, and you get the error.", "checks": [{"sel": "#app-error[role=\"alert\"]", "exists": true, "label": "A friendly error region with role=\"alert\""}, {"htmlContains": "unhandledrejection", "label": "The script catches unhandled promise rejections"}, {"htmlContains": "trackError(", "label": "Errors go to a trackError( function"}, {"htmlMatch": "function\\s+reportError\\b|(const|let|var)\\s+reportError\\b", "label": "Nothing replaces the browser's built-in reportError", "negate": true, "hint": "Rename your function to trackError so window.reportError keeps working."}]}, {"type": "concept", "heading": "Rollbacks and flags", "body": "Netlify and Vercel keep every deploy. Rolling back is one click on an older one, and it takes seconds. Feature flags let you ship code turned off, then turn it on for a few users first."}, {"type": "order", "prompt": "Order an incident.", "items": ["Notice: an alert or a user report", "Roll back to the last good deploy", "Find the cause in logs and error reports", "Fix it with a test that would have caught it", "Write a short note on what happened"], "explain": "Stop the damage before you investigate. Investigating a live outage costs users every minute.", "codeItems": false, "orderNote": "Order matters: roll back first, debug second."}, {"type": "mcq", "prompt": "A deploy broke checkout late at night. What is the fastest safe move?", "options": ["Debug it live on production", "Roll back to the previous deploy, then debug in the morning", "Turn off the whole site", "Push a guess and hope"], "answer": 1, "explain": "A rollback is tested, instant and reversible. A midnight hotfix is none of those."}]}, {"title": "Working like a pro: reviews, docs, and open source", "keywords": ["review", "pull", "request", "docs", "readme", "contributing", "open", "source", "semver", "changelog", "capstone"], "steps": [{"type": "concept", "heading": "Before you start: what you need", "body": "Your app's GitHub repo and its live deploy from the earlier lessons. Contributing to someone else's project needs only your GitHub account. Cost: free."}, {"type": "concept", "heading": "Pull request habits", "body": "Small changes, one idea each. A title that says what changed, a description that says why, and screenshots for anything visual. A reviewer should understand it in five minutes."}, {"type": "concept", "heading": "Giving and getting review", "body": "Comment on the code, not the person. Ask questions when unsure, say which comments block the merge, and suggest a fix when you can. When receiving, answer every comment, even with \"done\"."}, {"type": "mcq", "prompt": "Which review comment is most useful?", "options": ["This is wrong.", "Why not do it differently?", "This fetch has no catch, so a network error leaves the spinner forever. Wrap it and show .error?", "LGTM"], "answer": 2, "explain": "Specific problem, specific consequence, suggested fix."}, {"type": "order", "prompt": "Contribute to an open source project.", "items": ["Find an issue labeled good first issue", "Fork the repo", "Create a branch", "Make the change and run the tests", "Open a pull request that links the issue"], "explain": "Fork, branch, change, test, propose. Comment on the issue first so nobody duplicates the work.", "codeItems": false, "orderNote": "Each step needs the one before it."}, {"type": "concept", "heading": "Versions that mean something", "body": "Semantic versioning: MAJOR.MINOR.PATCH. Breaking change bumps major, new feature bumps minor, fix bumps patch. A CHANGELOG lists what changed in each version in plain words."}, {"type": "mcq", "prompt": "What belongs in a good bug report?", "options": ["Just \"it is broken\"", "Steps to reproduce, what you expected, what happened, and your browser and device", "A screenshot of the whole desktop", "The fix only"], "answer": 1, "explain": "If the maintainer can reproduce it in a minute, it gets fixed."}, {"type": "build", "prompt": "Expert capstone. Your page should carry the whole app: components in #cards-root, testable search, a not-found route, a CSP, an error fallback, a health check link, and a footer link to the repo. Confirm the rest of the stack outside Prexis and paste your live app URL.", "example": "Use your work from lessons 1 to 8. Add a status link, for example <a href=\"/api/health\">Status</a> in the footer.", "explain": "Typed, componentized, routed, backed by an API and a database, secured, tested, monitored and documented. You build and run real web apps.", "checks": [{"sel": "#cards-root .card", "count": 3, "label": "Cards rendered in #cards-root"}, {"sel": "[data-testid=\"search\"]", "exists": true, "label": "A testable search input"}, {"sel": "[data-route=\"not-found\"]", "exists": true, "label": "A not-found route"}, {"sel": "meta[http-equiv=\"Content-Security-Policy\"]", "exists": true, "label": "A Content-Security-Policy"}, {"cspOk": true, "label": "The policy still lets your own page load"}, {"sel": "#app-error[role=\"alert\"]", "exists": true, "label": "An error fallback"}, {"htmlContains": "/api/health", "label": "A link to /api/health"}, {"sel": "footer a[href*=\"github.com\"]", "exists": true, "label": "A footer link to the repo"}, {"confirm": true, "label": "TypeScript strict, unit tests and end to end tests run in CI"}, {"confirm": true, "label": "README covers setup, deploy and rollback; CONTRIBUTING.md, a PR template and a LICENSE exist"}, {"url": "appUrl", "label": "Your live app address", "kind": "site"}]}]}]}]}], "quickPicks": [], "overlay": {"core-js": {"track": "code", "blurb": "Bindings, lists, errors, async, objects, closures, reduce, copies."}, "web-pages": {"track": "web", "blurb": "HTML, CSS, box model, flex, grid, accessibility."}, "site-design": {"track": "web", "prereq": "web-pages", "blurb": "Hierarchy, type, copy, hosting."}, "seo": {"track": "web", "prereq": "site-design", "blurb": "Crawlers, titles, intent."}, "math": {"track": "quant", "blurb": "Percents, rates, probability."}, "thinking": {"track": "thinking", "blurb": "Arguments, correlation, estimation, bias."}, "money": {"track": "money", "blurb": "Pay yourself first, debt, investing."}, "sheets": {"track": "quant", "blurb": "Cells, references, functions, pivots."}, "writing": {"track": "writing", "blurb": "Fog, paragraphs, emails, revision."}}};

(function () {
  const extra = window.PREXIS_EXTRA;
  const root = window.PREXIS_CONTENT;
  if (!root || !extra) return;
  const overlay = extra.overlay || {};
  (root.courses || []).forEach((c) => {
    const o = overlay[c.id];
    if (!o) return;
    if (o.track) c.track = o.track;
    if (o.prereq) c.prereq = o.prereq;
    if (o.blurb) c.blurb = o.blurb;
  });
  root.courses = (root.courses || []).concat(extra.courses || []);
  root.quickPicks = (root.quickPicks || []).concat(extra.quickPicks || []);
})();
